# ============================================================================
# FAST CLIPBOARD COPY (Windows only - using clip.exe)
# ============================================================================
def copy_to_clipboard(text):
    """Copy text to clipboard using clip.exe (non-blocking, no lag)"""
    try:
        import subprocess
        # Use clip.exe - built into Windows, handles any text size
        process = subprocess.Popen(
            'clip.exe',
            stdin=subprocess.PIPE,
            shell=True,
            creationflags=subprocess.CREATE_NO_WINDOW
        )
        process.stdin.write(text.encode('utf-8'))
        process.stdin.close()
        # Don't wait for process to finish - makes it non-blocking
        return True
    except Exception as e:
        print(f"[Clipboard] Error: {e}")
        return False

# ============================================================================
# RESOLUTION PRESETS (for 4K monitor performance)
# ============================================================================
# Use command-line: python beetle_physics.py --res 720
# Or: python beetle_physics.py --res 1080 (default)
RESOLUTION_PRESETS = {
    '720': (1280, 720),    # 720p - Best performance
    '900': (1600, 900),    # 900p - Good balance
    '1080': (1920, 1080),  # 1080p - Default
    '1440': (2560, 1440),  # 1440p - High quality
    '4k': (3840, 2160),    # 4K - Native (slow on some systems)
}

def get_resolution_from_args():
    """Parse --res argument to get window resolution"""
    res_key = '1080'  # Default
    for i, arg in enumerate(sys.argv):
        if arg in ('--res', '-r', '--resolution') and i + 1 < len(sys.argv):
            res_key = sys.argv[i + 1].lower()
            break
        elif arg.startswith('--res='):
            res_key = arg.split('=')[1].lower()
            break

    if res_key in RESOLUTION_PRESETS:
        return RESOLUTION_PRESETS[res_key], res_key
    else:
        print(f"[Resolution] Unknown preset '{res_key}', using 1080p")
        print(f"[Resolution] Available: {', '.join(RESOLUTION_PRESETS.keys())}")
        return RESOLUTION_PRESETS['1080'], '1080'

def get_vsync_from_args():
    """Parse --vsync/--novsync arguments (default: OFF)"""
    for arg in sys.argv:
        if arg in ('--vsync',):
            print("[VSync] ENABLED (--vsync flag)")
            return True
    # Default: vsync OFF for better performance on varied hardware
    return False

def get_steam_connect_lobby():
    """Parse +connect_lobby argument from Steam friend join"""
    for i, arg in enumerate(sys.argv):
        if arg == '+connect_lobby' and i + 1 < len(sys.argv):
            lobby_id = sys.argv[i + 1]
            print(f"[Steam] Friend join detected! Lobby ID: {lobby_id}")
            return lobby_id
    return None

def get_fullscreen_from_args():
    """Parse --fullscreen argument and return screen resolution if enabled"""
    for arg in sys.argv:
        if arg in ('--fullscreen', '-f'):
            # Get screen resolution using ctypes (Windows)
            try:
                import ctypes
                user32 = ctypes.windll.user32
                screen_w = user32.GetSystemMetrics(0)
                screen_h = user32.GetSystemMetrics(1)
                print(f"[Fullscreen] ENABLED - using screen resolution {screen_w}x{screen_h}")
                return True, (screen_w, screen_h)
            except Exception as e:
                print(f"[Fullscreen] Failed to get screen resolution: {e}")
                return False, None
    return False, None

