# ============================================================================
# CONTROLLER SUPPORT
# ============================================================================
controllers = []  # List of connected Controller objects
STICK_DEADZONE = 0.4       # Forward/backward deadzone
STICK_TURN_DEADZONE = 0.32  # Turn deadzone (lower for responsive direction changes while charging)
TRIGGER_THRESHOLD = 0.3

# SDL Controller axis/button constants (raw integers for pygame compatibility)
AXIS_LEFTX = 0
AXIS_LEFTY = 1
AXIS_RIGHTX = 2
AXIS_RIGHTY = 3
AXIS_TRIGGERLEFT = 4
AXIS_TRIGGERRIGHT = 5
BUTTON_A = 0
BUTTON_B = 1
BUTTON_X = 2
BUTTON_Y = 3
BUTTON_LEFTSHOULDER = 9
BUTTON_RIGHTSHOULDER = 10

def init_controllers():
    """Initialize pygame controller subsystem. Call once at startup."""
    if not CONTROLLER_SUPPORT:
        return
    pygame.init()
    sdl_controller.init()
    _refresh_controllers()

def _refresh_controllers():
    """Rebuild controller list. Called on startup and device events."""
    global controllers
    # Close old controllers
    for ctrl in controllers:
        try:
            ctrl.quit()
        except:
            pass
    controllers = []
    for i in range(sdl_controller.get_count()):
        try:
            ctrl = sdl_controller.Controller(i)
            controllers.append(ctrl)
            print(f"[Controller] Found: {ctrl.name} (player {len(controllers)})")
        except:
            pass
    if not controllers:
        print("[Controller] No controllers detected")

def pump_controller_events():
    """Call once per frame. Handles hot-plug via events, ~0.01ms overhead."""
    if not CONTROLLER_SUPPORT:
        return
    try:
        for event in pygame.event.get():
            if event.type == pygame.CONTROLLERDEVICEADDED:
                print("[Controller] Device connected")
                _refresh_controllers()
            elif event.type == pygame.CONTROLLERDEVICEREMOVED:
                print("[Controller] Device disconnected")
                _refresh_controllers()
    except (SystemError, KeyError):
        # pygame/SDL can throw when controller connects/disconnects mid-frame
        print("[Controller] Hot-plug event error, refreshing controllers")
        _refresh_controllers()

def get_controller_inputs(ctrl, horn_type_id=0):
    """Read controller state and return input bitmask (same format as keyboard)."""
    if ctrl is None:
        return 0
    try:
        inputs = 0
        # Left stick: All movement (Y = forward/back, X = turn)
        left_y = ctrl.get_axis(AXIS_LEFTY) / 32767.0
        left_x = ctrl.get_axis(AXIS_LEFTX) / 32767.0
        if left_y < -STICK_DEADZONE:
            inputs |= INPUT_FORWARD
        elif left_y > STICK_DEADZONE:
            inputs |= INPUT_BACKWARD
        if left_x < -STICK_TURN_DEADZONE:
            inputs |= INPUT_LEFT
        elif left_x > STICK_TURN_DEADZONE:
            inputs |= INPUT_RIGHT

        # Right stick: Alternative horn controls (same mapping as XYAB)
        right_y = ctrl.get_axis(AXIS_RIGHTY) / 32767.0
        right_x = ctrl.get_axis(AXIS_RIGHTX) / 32767.0

        # Face buttons + right stick: Horn controls (beetle-specific remapping)
        # Right stick mirrors XYAB: up=Y, down=A, left=X, right=B
        button_y = ctrl.get_button(BUTTON_Y) or (right_y < -STICK_DEADZONE)
        button_a = ctrl.get_button(BUTTON_A) or (right_y > STICK_DEADZONE)
        button_x = ctrl.get_button(BUTTON_X) or (right_x < -STICK_DEADZONE)
        button_b = ctrl.get_button(BUTTON_B) or (right_x > STICK_DEADZONE)

        if horn_type_id == 0 or horn_type_id == 4:  # Rhino or Atlas: swap X/B for intuitive yaw
            # Y/A: up/down (same as default)
            if button_y:
                inputs |= INPUT_HORN_UP
            if button_a:
                inputs |= INPUT_HORN_DOWN
            # X/B: swapped for intuitive left/right sweep
            if button_x:
                inputs |= INPUT_HORN_RIGHT  # Swapped
            if button_b:
                inputs |= INPUT_HORN_LEFT   # Swapped
        elif horn_type_id == 5:  # Bombardier: Y/A=body, X/B=fire
            # Y/A: body up/down
            if button_y:
                inputs |= INPUT_HORN_LEFT   # Body up
            if button_a:
                inputs |= INPUT_HORN_RIGHT  # Body down
            # X/B: fire direction
            if button_x:
                inputs |= INPUT_HORN_DOWN   # Fire behind
            if button_b:
                inputs |= INPUT_HORN_UP     # Fire forward
        elif horn_type_id == 6:  # Spider: Y/A=body, X/B=silk type
            # Y/A: body up/down
            if button_y:
                inputs |= INPUT_HORN_LEFT   # Body up
            if button_a:
                inputs |= INPUT_HORN_RIGHT  # Body down
            # X/B: silk type
            if button_x:
                inputs |= INPUT_HORN_DOWN   # Normal silk
            if button_b:
                inputs |= INPUT_HORN_UP     # Fast silk
        else:  # Stag, Hercules, Scorpion - default mapping
            if button_y:
                inputs |= INPUT_HORN_UP
            if button_a:
                inputs |= INPUT_HORN_DOWN
            if button_x:
                inputs |= INPUT_HORN_LEFT
            if button_b:
                inputs |= INPUT_HORN_RIGHT
        return inputs
    except:
        return 0  # Controller disconnected or error

def _get_keyboard_inputs(window, player='blue', network_mode=False, horn_type_id=0):
    """
    Read keyboard inputs and return 8-bit input state.

    This abstraction allows:
    - Easy addition of controller support later
    - Network sync (just send the 8-bit value)
    - Input replay/recording
    - Key remapping

    Args:
        window: The game window to read key presses from
        player: 'blue' or 'red' to select key bindings
        network_mode: If True, use WASD + arrow keys instead of split keyboard
        horn_type_id: Beetle type for network mode arrow key remapping

    Returns:
        int: 8-bit input state (0-255)
    """
    if network_mode:
        keys = NETWORK_KEYS
    else:
        keys = BLUE_KEYS if player == 'blue' else RED_KEYS
    inputs = 0

    # Movement keys (same for all beetle types)
    if window.is_pressed(keys['forward']):
        inputs |= INPUT_FORWARD
    if window.is_pressed(keys['backward']):
        inputs |= INPUT_BACKWARD
    if window.is_pressed(keys['left']):
        inputs |= INPUT_LEFT
    if window.is_pressed(keys['right']):
        inputs |= INPUT_RIGHT

    if network_mode:
        # Beetle-specific arrow key remapping for intuitive controls
        if horn_type_id == 0 or horn_type_id == 4:  # Rhino or Atlas: swap LEFT<->RIGHT for intuitive yaw
            if window.is_pressed(ti.GUI.UP):
                inputs |= INPUT_HORN_UP
            if window.is_pressed(ti.GUI.DOWN):
                inputs |= INPUT_HORN_DOWN
            if window.is_pressed(ti.GUI.LEFT):
                inputs |= INPUT_HORN_RIGHT  # Swapped
            if window.is_pressed(ti.GUI.RIGHT):
                inputs |= INPUT_HORN_LEFT   # Swapped
        elif horn_type_id == 5:  # Bombardier: UP/DOWN=body, LEFT/RIGHT=fire
            if window.is_pressed(ti.GUI.UP):
                inputs |= INPUT_HORN_LEFT   # Body up
            if window.is_pressed(ti.GUI.DOWN):
                inputs |= INPUT_HORN_RIGHT  # Body down
            if window.is_pressed(ti.GUI.LEFT):
                inputs |= INPUT_HORN_DOWN   # Fire behind
            if window.is_pressed(ti.GUI.RIGHT):
                inputs |= INPUT_HORN_UP     # Fire forward
        elif horn_type_id == 6:  # Spider: UP/DOWN=body, LEFT/RIGHT=silk types
            if window.is_pressed(ti.GUI.UP):
                inputs |= INPUT_HORN_LEFT   # Body up
            if window.is_pressed(ti.GUI.DOWN):
                inputs |= INPUT_HORN_RIGHT  # Body down
            if window.is_pressed(ti.GUI.LEFT):
                inputs |= INPUT_HORN_DOWN   # Normal silk
            if window.is_pressed(ti.GUI.RIGHT):
                inputs |= INPUT_HORN_UP     # Fast silk
        else:  # Stag, Hercules, Scorpion - default mapping
            if window.is_pressed(keys['horn_up']):
                inputs |= INPUT_HORN_UP
            if window.is_pressed(keys['horn_down']):
                inputs |= INPUT_HORN_DOWN
            if window.is_pressed(keys['horn_left']):
                inputs |= INPUT_HORN_LEFT
            if window.is_pressed(keys['horn_right']):
                inputs |= INPUT_HORN_RIGHT
    else:
        # Local mode - standard mapping
        if window.is_pressed(keys['horn_up']):
            inputs |= INPUT_HORN_UP
        if window.is_pressed(keys['horn_down']):
            inputs |= INPUT_HORN_DOWN
        if window.is_pressed(keys['horn_left']):
            inputs |= INPUT_HORN_LEFT
        if window.is_pressed(keys['horn_right']):
            inputs |= INPUT_HORN_RIGHT

    return inputs


def get_local_inputs(window, player='blue', network_mode=False, horn_type_id=0):
    """Get inputs from controller (if available) combined with keyboard."""
    # Get keyboard inputs (always works)
    keyboard_inputs = _get_keyboard_inputs(window, player, network_mode, horn_type_id)

    # Add controller inputs if available
    controller_inputs = 0
    if CONTROLLER_SUPPORT and controllers:
        if network_mode:
            # Network mode: first controller controls local beetle
            controller_inputs = get_controller_inputs(controllers[0], horn_type_id)
        elif player == 'blue':
            controller_inputs = get_controller_inputs(controllers[0], horn_type_id)
        elif player == 'red' and len(controllers) >= 2:
            controller_inputs = get_controller_inputs(controllers[1], horn_type_id)

    # Combine both input sources (allows hybrid play)
    return keyboard_inputs | controller_inputs


class InputBuffer:
    """
    Delay-based lockstep input buffer for P2P networking.

    Key features:
    - Symmetric input delay: Both players have same delay for fairness
    - Lockstep: Won't simulate a frame until we have BOTH inputs
    - Frame synchronization: Both clients process same inputs at same frame

    For local play, delay can be set to 0.
    For network play, delay is fixed at 8 frames (~133ms at 60Hz).
    """

    # Input delay in frames - fixed for consistent sync between clients
    # 8 frames = ~133ms at 60Hz - covers most connections without desyncs
    NETWORK_INPUT_DELAY = 8

    def __init__(self, delay_frames=0):
        self.delay = delay_frames
        self.local_inputs = {}    # frame_num -> input_bits (our inputs)
        self.remote_inputs = {}   # frame_num -> input_bits (opponent inputs)
        self.current_frame = 0    # The frame we're about to simulate
        self.is_network_mode = False  # Set True when connected to opponent
        self.local_player_id = 0  # 0 = host (blue), 1 = guest (red)

        # Lockstep state
        self.waiting_for_remote = False  # True when blocked waiting for opponent
        self.frames_waited = 0  # How many frames we've been waiting
        self.max_wait_frames = 180  # 3 seconds at 60fps before timeout

        # Network stats
        self.remote_frame_received = -1  # Highest frame number received from opponent
        self.frames_behind = 0  # How far behind opponent we are

        # Debug stats for network responsiveness analysis
        self.debug_wait_count = 0  # How many times we waited for opponent
        self.debug_predict_count = 0  # How many times we used input prediction
        self.debug_total_frames = 0  # Total frames processed
        self.debug_last_report = 0  # Last frame we printed debug info

        # State sync (host sends authoritative state periodically)
        self.last_state_sync_frame = 0
        self.state_sync_interval = 30  # Every 30 frames (~500ms)

        # Jitter buffer for handling variable ping (professional netcode technique)
        self.ping_samples = []  # Last 60 ping samples for percentile calculation
        self.max_ping_samples = 60  # ~1 second of samples at 60Hz
        self.last_delay_recalc_time = 0.0  # Real time when we last recalculated delay
        self.delay_recalc_interval = 5.0  # Recalculate delay every 5 seconds

    def add_local(self, inputs):
        """Store local player's inputs for current frame + delay."""
        # Store at current_frame (we'll use it when we reach that frame)
        self.local_inputs[self.current_frame] = inputs

    def add_remote(self, frame, inputs):
        """Store remote player's inputs (received from network)."""
        self.remote_inputs[frame] = inputs

        # Track highest frame received for sync detection
        if frame > self.remote_frame_received:
            self.remote_frame_received = frame

    def get_sim_frame(self):
        """Get the frame number we should be simulating (current - delay)."""
        return max(0, self.current_frame - self.delay)

    def can_simulate(self):
        """
        Check if we can simulate the next physics frame.
        In lockstep, we need BOTH players' inputs for the frame.
        """
        if not self.is_network_mode:
            return True  # Local mode: always can simulate

        sim_frame = self.get_sim_frame()

        # Check if we have local input for this frame
        has_local = sim_frame in self.local_inputs

        # Check if we have remote input for this frame
        # Due to UDP packet loss, we might be missing exact frames
        # If we have a newer frame, use that instead (input prediction)
        has_remote = sim_frame in self.remote_inputs
        used_prediction = False
        if not has_remote and self.remote_frame_received >= sim_frame:
            # We have newer inputs - find the closest one and use it
            for f in range(sim_frame, self.remote_frame_received + 1):
                if f in self.remote_inputs:
                    # Copy this input to the missing frame (assume same input)
                    self.remote_inputs[sim_frame] = self.remote_inputs[f]
                    has_remote = True
                    used_prediction = True
                    self.debug_predict_count += 1
                    break

        if has_local and has_remote:
            self.waiting_for_remote = False
            self.frames_waited = 0
            self.debug_total_frames += 1
            return True
        else:
            if not has_remote:
                self.waiting_for_remote = True
                self.frames_waited += 1
                self.debug_wait_count += 1
            return False

    def get_frame_inputs(self, frame):
        """
        Get inputs for a physics frame.

        Returns: (blue_inputs, red_inputs)
        """
        if not self.is_network_mode:
            # Local mode: simple delay-based lookup
            target = frame - self.delay
            local = self.local_inputs.get(target, 0)
            remote = self.remote_inputs.get(target, 0)
            return local, remote

        # Network lockstep mode
        sim_frame = self.get_sim_frame()
        local = self.local_inputs.get(sim_frame, 0)
        remote = self.remote_inputs.get(sim_frame, 0)

        if self.local_player_id == 0:
            # We are host (blue): local=blue, remote=red
            return local, remote
        else:
            # We are guest (red): local=red, remote=blue
            return remote, local

    def has_inputs_for_frame(self, frame):
        """Check if we have all inputs needed to process a frame."""
        if not self.is_network_mode:
            target = frame - self.delay
            if target < 0:
                return True
            return target in self.local_inputs and target in self.remote_inputs

        # In lockstep mode, use can_simulate()
        return self.can_simulate()

    def advance_frame(self):
        """Move to next frame."""
        self.current_frame += 1

        # Cleanup old inputs (keep last 120 frames = 2 seconds)
        cleanup_threshold = self.current_frame - 120
        self.local_inputs = {k: v for k, v in self.local_inputs.items() if k > cleanup_threshold}
        self.remote_inputs = {k: v for k, v in self.remote_inputs.items() if k > cleanup_threshold}

    def _get_percentile_ping(self, percentile=90):
        """Get the Nth percentile ping from samples (jitter buffer technique).

        Using 90th percentile instead of average accounts for ping spikes,
        preventing input drops during momentary latency increases.
        """
        if not self.ping_samples:
            return 60  # Default if no samples yet

        sorted_samples = sorted(self.ping_samples)
        index = int(len(sorted_samples) * percentile / 100)
        index = min(index, len(sorted_samples) - 1)
        return sorted_samples[index]

    def set_network_delay(self, ping_ms):
        """Set input delay based on measured network latency.

        Called at match start to set initial delay.
        """
        # Add to samples for jitter buffer
        self.ping_samples.append(ping_ms)
        if len(self.ping_samples) > self.max_ping_samples:
            self.ping_samples.pop(0)

        # Convert ping to frames: delay = (ping/2) / 16.67ms per frame
        # Add 1 frame safety margin
        one_way_ms = ping_ms / 2.0
        delay_frames = int(one_way_ms / 16.67) + 1
        # Clamp between 2 and 8 frames (higher max handles up to ~250ms ping)
        self.delay = max(2, min(8, delay_frames))
        self.last_delay_recalc_time = time.time()
        print(f"[InputBuffer] Set delay to {self.delay} frames for {ping_ms:.0f}ms ping")

    def update_ping_sample(self, ping_ms):
        """Add ping sample and periodically recalculate delay.

        Call this every frame during online play with current ping.
        Uses jitter buffer (90th percentile) for stable delay calculation.
        Limits delay changes to ±1 frame to prevent jarring shifts.
        """
        # Add sample to rolling buffer
        self.ping_samples.append(ping_ms)
        if len(self.ping_samples) > self.max_ping_samples:
            self.ping_samples.pop(0)

        # Check if it's time to recalculate delay
        current_time = time.time()
        if current_time - self.last_delay_recalc_time < self.delay_recalc_interval:
            return  # Not time yet

        self.last_delay_recalc_time = current_time

        # Use 90th percentile to handle ping spikes
        percentile_ping = self._get_percentile_ping(90)

        # Calculate target delay
        one_way_ms = percentile_ping / 2.0
        target_delay = int(one_way_ms / 16.67) + 1
        target_delay = max(2, min(8, target_delay))

        # Limit change to ±1 frame per recalculation to prevent jarring shifts
        if target_delay > self.delay:
            new_delay = min(self.delay + 1, target_delay)
        elif target_delay < self.delay:
            new_delay = max(self.delay - 1, target_delay)
        else:
            new_delay = self.delay

        if new_delay != self.delay:
            print(f"[InputBuffer] Adjusted delay: {self.delay} -> {new_delay} frames (90th percentile ping: {percentile_ping:.0f}ms)")
            self.delay = new_delay

    def reset(self):
        """Reset buffer for new match."""
        self.local_inputs.clear()
        self.remote_inputs.clear()
        self.current_frame = 0
        self.waiting_for_remote = False
        self.frames_waited = 0
        self.remote_frame_received = -1
        self.frames_behind = 0
        self.last_state_sync_frame = 0
        # Reset jitter buffer state for fresh match
        self.ping_samples.clear()
        self.last_delay_recalc_time = time.time()


# Global input buffer instance (used by main loop)
input_buffer = InputBuffer(delay_frames=0)  # 0 delay for local play

# ============================================================================
# NETWORK STATE (for online play)
# ============================================================================
network_manager = None          # NetworkManager instance (created when hosting/joining)
game_state = GAME_STATE_TITLE   # Start at title screen
local_player_id = 0             # 0 = blue/host, 1 = red/guest
title_transition_timer = 0.0    # Timer for title-to-game camera transition
arena_lights_timer = 0.0        # Timer for dramatic arena lights turn-on effect
ARENA_LIGHTS_FADEIN = 0.8       # Duration for lights to fade in (seconds)
lobby_id_input = ""             # Text input for joining lobby by ID
network_error_msg = ""          # Error message to display

def cleanup_network():
    """Clean up network resources on exit to prevent orphaned Steam sockets."""
    global network_manager
    if network_manager is not None:
        print("[Network] Cleaning up on exit...")
        try:
            # Send disconnect message to peer if connected
            if network_manager.connected:
                network_manager.send_disconnect()
            network_manager.shutdown()
        except Exception as e:
            print(f"[Network] Cleanup error (ignorable): {e}")
        network_manager = None
        print("[Network] Cleanup complete")

# Register cleanup to run on exit (prevents orphaned Steam sockets)
atexit.register(cleanup_network)

