# Beetle state with physics
class Beetle:
    def __init__(self, x, z, rotation, color):
        self.x = x
        self.z = z
        self.vx = 0.0  # Velocity
        self.vz = 0.0
        self.y = 1.0  # Vertical position (floor level)
        self.vy = 0.0  # Vertical velocity
        self.on_ground = True  # Ground contact state
        # Yaw rotation (spin around vertical axis)
        self.rotation = rotation
        self.target_rotation = rotation
        self.angular_velocity = 0.0  # Spin speed (radians/sec)
        self.moment_of_inertia = BEETLE_RADIUS * MOMENT_OF_INERTIA_FACTOR  # Resistance to rotation (higher = more stable, less flinging)

        # Pitch rotation (forward/backward tilt)
        self.pitch = 0.0  # Body pitch angle (radians, positive = front up)
        self.pitch_velocity = 0.0  # Pitch angular velocity (radians/sec)
        self.pitch_inertia = BEETLE_RADIUS * MOMENT_OF_INERTIA_FACTOR  # Same inertia as yaw

        # Roll rotation (side-to-side tilt)
        self.roll = 0.0  # Body roll angle (radians, positive = right side up)
        self.roll_velocity = 0.0  # Roll angular velocity (radians/sec)
        self.roll_inertia = BEETLE_RADIUS * MOMENT_OF_INERTIA_FACTOR  # Same inertia as yaw
        self.color = color
        self.radius = BEETLE_RADIUS
        self.occupied_voxels = set()  # Track voxel positions for accurate collision

        # Animation state for procedural leg movement
        self.walk_phase = 0.0  # Current walk cycle phase (0 to 2π)
        self.prev_walk_phase = 0.0  # Previous frame walk phase (for leg dust touchdown detection)
        self.spin_dust_timer = 0.0  # Timer for spinning dust spawn interval
        self.spin_dust_leg_index = 0  # Current leg index for spinning dust pattern (0-5)
        self.is_moving = False  # Whether beetle is actively walking
        self.is_moving_backward = False  # True when moving backward (for dust/animation)
        self.is_rotating_only = False  # True when rotating without forward movement
        self.rotation_direction = 0  # -1 = left, 0 = none, 1 = right
        self.is_completing_animation = False  # True when finishing walk cycle after input stops
        self.target_walk_phase = 0.0  # Target neutral phase (0 or π) for animation completion
        self.completion_speed = 5.0  # Speed multiplier for completing animation (rad/s)

        # Smoothed collision normal for stable contact resolution
        self.contact_normal_x = 0.0  # Filtered collision normal X component
        self.contact_normal_y = 0.0  # Filtered collision normal Y component (prevents first-contact jump)
        self.contact_normal_z = 0.0  # Filtered collision normal Z component

        # Horn control state
        self.horn_pitch = HORN_DEFAULT_PITCH  # Vertical angle in radians - starts at +10°
        self.horn_yaw = 0.0    # Horizontal angle (stag=pincer spread, rhino=horn yaw) in radians
        self.horn_pitch_velocity = 0.0  # Rate of change of horn pitch (radians/sec)
        self.horn_yaw_velocity = 0.0  # Rate of change of horn yaw (radians/sec)
        self.horn_pitch_damping = 0.0  # Horn pitch resistance during collision (0.0-1.0)
        self.horn_yaw_damping = 0.0    # Horn yaw resistance during collision (0.0-1.0)

        # OPTIMIZATION: Cached horn tip positions to avoid recalculating every frame
        self.cached_horn_pitch = HORN_DEFAULT_PITCH  # Last pitch used for calculation
        self.cached_horn_yaw = 0.0  # Last yaw used for calculation
        self.cached_min_distance = 999.0  # Cached minimum distance result

        # Horn geometry (set during geometry generation)
        self.horn_shaft_len = 12  # Default horn shaft length in voxels
        self.horn_prong_len = 5   # Default horn prong length in voxels
        self.horn_length = 17.0   # Cached total horn reach (updated when geometry changes)
        self.horn_type = "rhino"  # Horn type: "rhino" (single horn), "stag" (dual pincers), "hercules" (dual jaws), or "scorpion"
        self.horn_type_id = HORN_TYPE_IDS["rhino"]  # OPTIMIZATION: Integer ID for fast lookup (avoids string comparisons)
        self.silk_speed_mult = 1.0  # Silk speed multiplier (set each frame based on body/floor silk)

        # Speed boost system - builds over 5 sec of holding forward/backward
        self.forward_hold_time = 0.0   # Seconds holding forward
        self.backward_hold_time = 0.0  # Seconds holding backward
        self.forward_bonus = 0.0       # 0.0 to 0.30 (30% max bonus)
        self.backward_bonus = 0.0      # 0.0 to 0.30 (30% max bonus)
        self.body_pitch_offset = 0.0  # Static body tilt angle (radians) - calculated from leg geometry for scorpion

        # Scorpion stinger control (VB/NM keys)
        self.stinger_curvature = 0.0  # Stinger curvature offset (-1.0 to +1.0): negative=dart forward, positive=pull back, 0=neutral
        self.tail_rotation_angle = 20.0  # Tail rotation angle in degrees (rests at max up, V/N push down)

        # Center of gravity tracking (for edge tipping physics)
        self.cog_x = x  # Center of gravity X
        self.cog_y = 1.0 + 3.0  # Center of gravity Y (approximate beetle center)
        self.cog_z = z  # Center of gravity Z

        # Collision cooldown timers
        self.lift_cooldown = 0.0  # Time remaining before next lift can be applied (seconds)
        self.tip_cooldown = 0.0   # Time remaining before next tipping torque (separate from lift)

        # Predictive collision smoothing (prevents horn clipping during fast spins)
        self.predictive_push_x = 0.0
        self.predictive_push_z = 0.0

        # Body rotation damping state (Phase 3: Directional Rotation Prevention)
        self.body_rotation_damping = 0.0  # Rotation resistance after collision (0.0-1.0)
        self.collision_spin_direction = 0  # Which way collision made us spin (-1=CCW, 0=none, 1=CW)
        self.in_horn_collision = False  # True when actively in horn-to-horn collision

        # Beetle active state (for fall death)
        self.active = True  # False when beetle has fallen off arena
        self.is_falling = False  # True when beetle has passed point of no return
        self.guest_death_falling = False  # True when guest receives death event and beetle is falling to explode
        self.has_exploded = False  # True when death particle explosion has been triggered
        self.explosion_delay = 0.0  # Delay before particles start spawning
        self.explosion_timer = 0.0  # Timer for gradual particle spawning (0.3 seconds)
        self.explosion_pos_x = 0.0  # Store explosion position
        self.explosion_pos_y = 0.0
        self.explosion_pos_z = 0.0
        self.is_lifted_high = False  # True when lifted significantly above ground (for leg spaz animation)

        # Hook interior tracking for stag beetles (parallel to body geometry cache)
        self.body_hook_interior_flags = []  # 1=hook interior, 0=regular (4th element from stag pincer voxels)

        # Previous state for fixed timestep interpolation
        self.prev_x = x
        self.prev_y = 1.0
        self.prev_z = z
        self.prev_rotation = rotation
        self.prev_pitch = 0.0
        self.prev_roll = 0.0
        self.prev_horn_pitch = HORN_DEFAULT_PITCH
        self.prev_horn_yaw = 0.0
        self.prev_tail_rotation_angle = 20.0

    def save_previous_state(self):
        """Save current state as previous for interpolation"""
        self.prev_x = self.x
        self.prev_y = self.y
        self.prev_z = self.z
        self.prev_rotation = self.rotation
        self.prev_pitch = self.pitch
        self.prev_roll = self.roll
        self.prev_horn_pitch = self.horn_pitch
        self.prev_horn_yaw = self.horn_yaw
        self.prev_tail_rotation_angle = self.tail_rotation_angle

    def apply_force(self, fx, fz, dt):
        """Add force to velocity"""
        self.vx += fx * dt
        self.vz += fz * dt

    def update_physics(self, dt):
        """Apply friction and update position"""
        # === COLLISION COOLDOWN TIMERS ===
        # Decrement lift cooldown timer (prevents multi-frame lift application)
        if self.lift_cooldown > 0.0:
            self.lift_cooldown = max(0.0, self.lift_cooldown - dt)
        # Decrement tip cooldown timer (separate from lift - for horn tipping torque)
        if self.tip_cooldown > 0.0:
            self.tip_cooldown = max(0.0, self.tip_cooldown - dt)

        # Decay horn pitch/yaw damping when not in contact (Phase 2: Horn Clipping Prevention)
        if self.horn_pitch_damping > 0.0:
            self.horn_pitch_damping = max(0.0, self.horn_pitch_damping - HORN_DAMPING_DECAY_RATE * dt)
        if self.horn_yaw_damping > 0.0:
            self.horn_yaw_damping = max(0.0, self.horn_yaw_damping - HORN_DAMPING_DECAY_RATE * dt)

        # Clear horn collision flag (will be reset each frame if still colliding)
        self.in_horn_collision = False

        # Decay body rotation damping after collision (Phase 3: Directional Rotation Prevention)
        if self.body_rotation_damping > 0.0:
            self.body_rotation_damping = max(0.0, self.body_rotation_damping - BODY_ROTATION_DAMPING_DECAY * dt)
            # Clear spin direction when damping reaches zero
            if self.body_rotation_damping == 0.0:
                self.collision_spin_direction = 0

        # === GRAVITY SYSTEM (Phase 1) ===
        # Air resistance (quadratic drag - lightweight calculation)
        # Skip air resistance for ball to prevent "hanging" at arc peak
        if abs(self.vy) > 1.0 and self.horn_type != "ball":
            air_drag = self.vy * abs(self.vy) * AIR_RESISTANCE
            self.vy -= air_drag * dt

        # Apply gravity (always on) - use global adjustable gravity
        self.vy -= physics_params["GRAVITY"] * dt

        # Apply vertical velocity
        self.y += self.vy * dt

        # Cap vertical velocity to prevent outlier launches (hard safety limit)
        if self.vy > MAX_VERTICAL_VELOCITY:
            self.vy = MAX_VERTICAL_VELOCITY

        # Ground contact will be determined by floor collision detection in main loop
        # (No hardcoded floor level here - floor is detected via voxel checking)

        # === HORIZONTAL PHYSICS (existing) ===
        # Apply linear friction (skip for ball when airborne to allow proper arc)
        if self.horn_type == "ball":
            # Ball uses its own rolling friction only when on ground (applied in main loop)
            pass
        else:
            self.vx *= FRICTION
            self.vz *= FRICTION

        # Apply angular friction (yaw)
        # Ball uses lighter angular friction for better spin retention
        if self.horn_type == "ball":
            ball_angular_friction = physics_params.get("BALL_ANGULAR_FRICTION", 0.98)
            self.angular_velocity *= ball_angular_friction
        else:
            self.angular_velocity *= ANGULAR_FRICTION

        # Apply angular friction (pitch/roll) - different damping based on ground contact
        if self.on_ground:
            # Heavy damping when on ground for stability
            self.pitch_velocity *= ANGULAR_FRICTION * 0.9  # Extra damping
            self.roll_velocity *= ANGULAR_FRICTION * 0.9
        else:
            # Light damping when airborne to allow dramatic tumbling (tunable via slider)
            airborne_damping = physics_params.get("AIRBORNE_DAMPING", 0.98)
            self.pitch_velocity *= airborne_damping
            self.roll_velocity *= airborne_damping

        # Ground restoring torque - automatically level out when on ground
        # Only apply strong restoring when beetle is settled, not just bouncing
        if self.on_ground and abs(self.vy) < 2.0:  # Must be on ground AND not bouncing up/down
            # Apply torque to bring pitch/roll back to zero (level)
            RESTORING_STRENGTH = physics_params.get("RESTORING_STRENGTH", 35.0)
            self.pitch_velocity -= self.pitch * RESTORING_STRENGTH * dt
            self.roll_velocity -= self.roll * RESTORING_STRENGTH * dt
        elif self.on_ground and abs(self.vy) >= 2.0:
            # Bouncing/landing - apply moderate restoring to allow tumbling but still settle
            WEAK_RESTORING = physics_params.get("WEAK_RESTORING", 25.0)
            self.pitch_velocity -= self.pitch * WEAK_RESTORING * dt
            self.roll_velocity -= self.roll * WEAK_RESTORING * dt

        # Clamp linear speed (different max for forward vs backward)
        speed = math.sqrt(self.vx**2 + self.vz**2)
        if speed > 0.01:  # Avoid division by zero
            # Calculate direction beetle is moving relative to facing direction
            forward_x = math.cos(self.rotation)
            forward_z = math.sin(self.rotation)
            dot_product = self.vx * forward_x + self.vz * forward_z

            # Apply different speed caps based on direction (use tunable params)
            # Spider has lower base speed, Scorpion is medium
            if self.horn_type_id == 6:  # Spider
                base_forward = 8.0
                base_backward = 6.0
            elif self.horn_type_id == 3:  # Scorpion
                base_forward = 9.0
                base_backward = 6.0
            else:
                base_forward = physics_params.get("FORWARD_SPEED", 7.0)
                base_backward = physics_params.get("BACKWARD_SPEED", 5.0)
            # Silk speed multiplier adjusts max speed (spider boost on floor silk)
            # Speed boost from holding: forward up to 70%, backward up to 30%
            forward_max = base_forward * self.silk_speed_mult * (1.0 + self.forward_bonus)
            backward_max = base_backward * self.silk_speed_mult * (1.0 + self.backward_bonus)
            if dot_product >= 0:  # Moving forward
                if speed > forward_max:
                    self.vx = (self.vx / speed) * forward_max
                    self.vz = (self.vz / speed) * forward_max
            else:  # Moving backward
                if speed > backward_max:
                    self.vx = (self.vx / speed) * backward_max
                    self.vz = (self.vz / speed) * backward_max

        # Clamp angular speeds (yaw, pitch, roll)
        if abs(self.angular_velocity) > MAX_ANGULAR_SPEED:
            self.angular_velocity = MAX_ANGULAR_SPEED if self.angular_velocity > 0 else -MAX_ANGULAR_SPEED

        # Different tilt speed caps based on ground contact
        if self.on_ground:
            MAX_TILT_SPEED = 8.0  # Conservative limit when on ground
        else:
            # Allow dramatic tumbling when airborne (tunable via slider)
            MAX_TILT_SPEED = physics_params.get("AIRBORNE_TILT_SPEED", 20.0)

        if abs(self.pitch_velocity) > MAX_TILT_SPEED:
            self.pitch_velocity = MAX_TILT_SPEED if self.pitch_velocity > 0 else -MAX_TILT_SPEED
        if abs(self.roll_velocity) > MAX_TILT_SPEED:
            self.roll_velocity = MAX_TILT_SPEED if self.roll_velocity > 0 else -MAX_TILT_SPEED

        # Update horizontal position
        self.x += self.vx * dt
        self.z += self.vz * dt

        # Update rotation angles (yaw, pitch, roll)
        self.pitch += self.pitch_velocity * dt
        self.roll += self.roll_velocity * dt

        # Clamp pitch/roll only when on ground - allow full rotations when airborne
        if self.on_ground:
            # Tunable max tilt angle when grounded (slider controls in degrees, converted to radians)
            ground_tilt_degrees = physics_params.get("GROUND_TILT_ANGLE", 60.0)
            MAX_TILT_ANGLE = math.radians(ground_tilt_degrees)
            self.pitch = max(-MAX_TILT_ANGLE, min(MAX_TILT_ANGLE, self.pitch))
            self.roll = max(-MAX_TILT_ANGLE, min(MAX_TILT_ANGLE, self.roll))
        # When airborne, allow full 360° tumbling (no clamping)

    def arena_collision(self):
        """Bounce off arena walls"""
        dist = math.sqrt(self.x**2 + self.z**2)
        if dist > ARENA_RADIUS - self.radius:
            # Push back
            angle = math.atan2(self.z, self.x)
            self.x = math.cos(angle) * (ARENA_RADIUS - self.radius)
            self.z = math.sin(angle) * (ARENA_RADIUS - self.radius)

            # Bounce velocity
            normal_x = self.x / dist
            normal_z = self.z / dist
            dot = self.vx * normal_x + self.vz * normal_z
            self.vx -= 2 * dot * normal_x * 0.5
            self.vz -= 2 * dot * normal_z * 0.5

# Game state
match_winner = None  # Legacy variable, no longer used (kept for compatibility with reset_match)
blue_celebrating = False  # True when blue scores (red died)
red_celebrating = False   # True when red scores (blue died)
victory_pulse_timer = 0.0  # Legacy timer (kept for compatibility)
blue_pulse_timer = 0.0  # Independent timer for blue's celebration
red_pulse_timer = 0.0   # Independent timer for red's celebration
blue_confetti_timer = 0.0  # Independent confetti timer for blue
red_confetti_timer = 0.0   # Independent confetti timer for red
VICTORY_PULSE_DURATION = 5.0  # Pulse for 5 seconds after victory
victory_confetti_timer = 0.0  # Legacy timer (kept for compatibility)
VICTORY_CONFETTI_DELAY = 0.6  # Wait 600ms before starting confetti
VICTORY_CONFETTI_INTERVAL = 0.15  # Spawn confetti every 0.15 seconds during victory
VICTORY_CONFETTI_PARTICLES = 30  # Particles per spawn wave

def reset_match():
    """Reset beetles to starting positions for new match"""
    global beetle_blue, beetle_red, match_winner, blue_celebrating, red_celebrating, victory_pulse_timer, victory_confetti_timer, previous_stinger_curvature, previous_tail_rotation, blue_horn_type, red_horn_type
    global blue_pulse_timer, red_pulse_timer, blue_confetti_timer, red_confetti_timer
    global spray_charges_blue, spray_charges_red, spray_recharge_timer_blue, spray_recharge_timer_red
    global stripe_color_blue, stripe_color_red
    global spray_aim_blue, spray_aim_red, spray_aim_y_blue, spray_aim_y_red, prev_spray_aim_blue, prev_spray_aim_red
    global spider_aim_blue, spider_aim_red, prev_spider_aim_blue, prev_spider_aim_red
    global silk_charge_blue, silk_charge_red, silk_might_exist
    global floor_cache_blue, floor_cache_red, floor_cache_ball
    global ball_last_render, spray_might_exist
    global venom_charges_blue, venom_charges_red, venom_recharge_timer_blue, venom_recharge_timer_red
    global venom_cooldown_blue, venom_cooldown_red, venom_burst_remaining_blue, venom_burst_remaining_red
    global venom_tip_color_blue, venom_tip_color_red
    global physics_frame
    global opponent_disconnected, opponent_left_gracefully, disconnect_timer, reconnect_banner_timer
    global blue_score, red_score, donut_mode, x_stage_mode, figure8_mode, yinyang_mode, square_bridge_mode
    global blue_downwash_active, blue_downwash_strength, blue_downwash_x, blue_downwash_z, blue_downwash_dust_timer, blue_downwash_fade_timer
    global red_downwash_active, red_downwash_strength, red_downwash_x, red_downwash_z, red_downwash_dust_timer, red_downwash_fade_timer
    global tornado_mode, tornado_time, tornado_x, tornado_z, tornado_dust_timer, tornado_phase
    global sandstorm_mode, sandstorm_time, sandstorm_dust_timer, sandstorm_force_intensity, debris_cleanup_was_high
    global ufo_mode, ufo_time, ufo_phase, ufo_x, ufo_z, ufo_target_x, ufo_target_z, ufo_dust_timer, ufo_prev_x, ufo_prev_z

    # Sync GPU to ensure any pending operations complete before reset
    ti.sync()

    # Reset scores for new match (ensures host and guest start at 0-0)
    blue_score = 0
    red_score = 0

    # Reset input buffer and physics frame for new match (important for network sync)
    input_buffer.reset()
    physics_frame = 0

    # Get spawn positions based on arena mode (is_initial=True for game start)
    blue_x, blue_z, blue_rot = get_spawn_position(for_blue=True, is_initial=True)
    red_x, red_z, red_rot = get_spawn_position(for_blue=False, is_initial=True)
    beetle_blue = Beetle(blue_x, blue_z, blue_rot, simulation.BEETLE_BLUE)
    beetle_red = Beetle(red_x, red_z, red_rot, simulation.BEETLE_RED)
    match_winner = None
    blue_celebrating = False
    red_celebrating = False
    victory_pulse_timer = 0.0
    victory_confetti_timer = 0.0
    blue_pulse_timer = 0.0
    red_pulse_timer = 0.0
    blue_confetti_timer = 0.0
    red_confetti_timer = 0.0

    # Reset network disconnect state
    opponent_disconnected = False
    opponent_left_gracefully = False
    disconnect_timer = 0.0
    reconnect_banner_timer = 0.0

    # Reset spray charges for bombardier beetles
    spray_charges_blue = SPRAY_MAX_CHARGES
    spray_charges_red = SPRAY_MAX_CHARGES
    spray_recharge_timer_blue = 0.0
    spray_recharge_timer_red = 0.0
    # Reset stripe colors to full charge (neon green)
    stripe_color_blue = [0.5, 1.0, 0.3]
    stripe_color_red = [0.5, 1.0, 0.3]
    # Reset spray aim angles and Y velocity
    spray_aim_blue = 0.0
    spray_aim_red = 0.0
    spray_aim_y_blue = 0.0
    spray_aim_y_red = 0.0
    prev_spray_aim_blue = 0.0
    prev_spray_aim_red = 0.0

    # Reset spider aim angles
    spider_aim_blue = 0.0
    spider_aim_red = 0.0
    prev_spider_aim_blue = 0.0
    prev_spider_aim_red = 0.0

    # Reset spider silk charges
    silk_charge_blue = SILK_MAX_CHARGE
    silk_charge_red = SILK_MAX_CHARGE

    # Reset spider silk particles
    simulation.num_silk[None] = 0
    simulation.silk_on_blue[None] = 0
    simulation.silk_on_red[None] = 0
    simulation.silk_on_ball[None] = 0
    simulation.silk_under_blue[None] = 0
    simulation.silk_under_red[None] = 0
    simulation.silk_under_ball[None] = 0
    silk_might_exist = False  # GPU sync optimization flag

    # Reset floor collision cache (CPU optimization)
    floor_cache_blue = (None, None, -1000.0)
    floor_cache_red = (None, None, -1000.0)
    floor_cache_ball = (None, None, -1000.0)

    # Reset ball render cache (CPU optimization)
    ball_last_render = (None, None, None, None, None, None)

    # Reset spray existence flag (CPU optimization)
    spray_might_exist = False

    # Reset downwash state
    blue_downwash_active = False
    blue_downwash_strength = 0.0
    blue_downwash_x = 0.0
    blue_downwash_z = 0.0
    blue_downwash_dust_timer = 0.0
    blue_downwash_fade_timer = 0.0
    red_downwash_active = False
    red_downwash_strength = 0.0
    red_downwash_x = 0.0
    red_downwash_z = 0.0
    red_downwash_dust_timer = 0.0
    red_downwash_fade_timer = 0.0

    # Reset tornado hazard state
    tornado_mode = False
    tornado_time = 0.0
    tornado_x = 0.0
    tornado_z = 0.0
    tornado_dust_timer = 0.0
    tornado_phase = 0.0

    # Reset sandstorm hazard state
    sandstorm_mode = False
    sandstorm_time = 0.0
    sandstorm_dust_timer = 0.0
    sandstorm_force_intensity = 0.0
    debris_cleanup_was_high = False

    # Reset UFO hazard state
    ufo_mode = False
    ufo_time = 0.0
    ufo_phase = 0.0
    ufo_x = 0.0
    ufo_z = 0.0
    ufo_target_x = 0.0
    ufo_target_z = 0.0
    ufo_dust_timer = 0.0
    ufo_prev_x = 0.0
    ufo_prev_z = 0.0

    # Reset venom charges for scorpion beetles
    venom_charges_blue = VENOM_MAX_CHARGES
    venom_charges_red = VENOM_MAX_CHARGES
    venom_recharge_timer_blue = 0.0
    venom_recharge_timer_red = 0.0
    venom_cooldown_blue = 0.0
    venom_cooldown_red = 0.0
    venom_burst_remaining_blue = 0
    venom_burst_remaining_red = 0
    # Reset venom tip colors to full charge (bright purple)
    venom_tip_color_blue = [0.6, 0.2, 0.8]
    venom_tip_color_red = [0.6, 0.2, 0.8]

    # Restore beetle colors from saved window values (in case restart during victory pulse)
    b = window.blue_body_color
    simulation.blue_body_color[None] = ti.Vector([b[0], b[1], b[2]])
    b = window.blue_leg_color
    simulation.blue_leg_color[None] = ti.Vector([b[0], b[1], b[2]])
    b = window.blue_leg_tip_color
    simulation.blue_leg_tip_color[None] = ti.Vector([b[0], b[1], b[2]])
    b = window.blue_stripe_color
    simulation.blue_stripe_color[None] = ti.Vector([b[0], b[1], b[2]])
    b = window.blue_horn_tip_color
    simulation.blue_horn_tip_color[None] = ti.Vector([b[0], b[1], b[2]])

    r = window.red_body_color
    simulation.red_body_color[None] = ti.Vector([r[0], r[1], r[2]])
    r = window.red_leg_color
    simulation.red_leg_color[None] = ti.Vector([r[0], r[1], r[2]])
    r = window.red_leg_tip_color
    simulation.red_leg_tip_color[None] = ti.Vector([r[0], r[1], r[2]])
    r = window.red_stripe_color
    simulation.red_stripe_color[None] = ti.Vector([r[0], r[1], r[2]])
    r = window.red_horn_tip_color
    simulation.red_horn_tip_color[None] = ti.Vector([r[0], r[1], r[2]])

    # Reset scorpion tracking variables to prevent geometry cache desync
    previous_stinger_curvature = 0.0
    previous_tail_rotation = 20.0  # Tail rests at max up position

    # Preserve each beetle's horn_type on reset so control mapping stays correct
    beetle_blue.horn_type = blue_horn_type
    beetle_blue.horn_type_id = HORN_TYPE_IDS.get(blue_horn_type, 0)
    beetle_red.horn_type = red_horn_type
    beetle_red.horn_type_id = HORN_TYPE_IDS.get(red_horn_type, 0)

    # Camera always tracks from edge side (beetles in foreground)

    print("\n" + "="*50)
    print("NEW MATCH STARTED!")
    print("="*50 + "\n")


def send_local_beetle_config(network_mgr, is_host):
    """Send local player's beetle configuration to opponent including colors."""
    if not network_mgr:
        return

    if is_host:
        # Host controls blue beetle
        horn_type_id = HORN_TYPE_IDS.get(blue_horn_type, 0)
        network_mgr.send_beetle_config(
            horn_type_id,
            window.blue_horn_shaft_value,
            window.blue_horn_prong_value,
            window.blue_back_body_height_value,
            window.blue_body_length_value,
            window.blue_body_width_value,
            window.blue_leg_length_value,
            window.blue_body_color,
            window.blue_leg_color,
            window.blue_leg_tip_color,
            window.blue_stripe_color,
            window.blue_horn_tip_color
        )
    else:
        # Guest controls red beetle
        horn_type_id = HORN_TYPE_IDS.get(red_horn_type, 0)
        network_mgr.send_beetle_config(
            horn_type_id,
            window.red_horn_shaft_value,
            window.red_horn_prong_value,
            window.red_back_body_height_value,
            window.red_body_length_value,
            window.red_body_width_value,
            window.red_leg_length_value,
            window.red_body_color,
            window.red_leg_color,
            window.red_leg_tip_color,
            window.red_stripe_color,
            window.red_horn_tip_color
        )


def apply_remote_beetle_config(network_mgr):
    """Apply received opponent beetle configuration."""
    global blue_horn_type, red_horn_type

    if not network_mgr or not network_mgr.remote_beetle_config:
        return False

    config = network_mgr.remote_beetle_config
    network_mgr.remote_beetle_config = None  # Consume it

    # Reverse lookup horn type from ID
    horn_names = ["rhino", "stag", "hercules", "scorpion", "atlas", "bombardier", "spider"]
    horn_type = horn_names[config['horn_type_id']] if config['horn_type_id'] < len(horn_names) else "rhino"

    # Determine which beetle to update based on sender's player_id
    # player_id 0 = host = blue beetle, player_id 1 = guest = red beetle
    if config['player_id'] == 0:
        # Opponent is host, so update BLUE beetle (opponent's beetle)
        # Check if geometry changed (only rebuild if shape parameters changed, not just colors)
        geometry_changed = (
            blue_horn_type != horn_type or
            window.blue_horn_shaft_value != config['shaft'] or
            window.blue_horn_prong_value != config['prong'] or
            window.blue_back_body_height_value != config['back_body'] or
            window.blue_body_length_value != config['body_len'] or
            window.blue_body_width_value != config['body_width'] or
            window.blue_leg_length_value != config['leg_len']
        )
        blue_horn_type = horn_type
        window.blue_horn_shaft_value = config['shaft']
        window.blue_horn_prong_value = config['prong']
        window.blue_back_body_height_value = config['back_body']
        window.blue_body_length_value = config['body_len']
        window.blue_body_width_value = config['body_width']
        window.blue_leg_length_value = config['leg_len']
        # Apply colors if present (always update colors, no rebuild needed)
        if 'body_color' in config:
            window.blue_body_color = config['body_color']
            window.blue_leg_color = config['leg_color']
            window.blue_leg_tip_color = config['leg_tip_color']
            window.blue_stripe_color = config['stripe_color']
            window.blue_horn_tip_color = config['horn_tip_color']
            # Update simulation color fields
            simulation.blue_body_color[None] = ti.Vector([config['body_color'][0], config['body_color'][1], config['body_color'][2]])
            simulation.blue_leg_color[None] = ti.Vector([config['leg_color'][0], config['leg_color'][1], config['leg_color'][2]])
            simulation.blue_leg_tip_color[None] = ti.Vector([config['leg_tip_color'][0], config['leg_tip_color'][1], config['leg_tip_color'][2]])
            simulation.blue_stripe_color[None] = ti.Vector([config['stripe_color'][0], config['stripe_color'][1], config['stripe_color'][2]])
            simulation.blue_horn_tip_color[None] = ti.Vector([config['horn_tip_color'][0], config['horn_tip_color'][1], config['horn_tip_color'][2]])
        # Only rebuild geometry if shape parameters changed (prevents jumping when only colors change)
        if geometry_changed:
            rebuild_blue_beetle(
                config['shaft'], config['prong'], 4, config['back_body'],
                config['body_len'], config['body_width'], config['leg_len'],
                horn_type
            )
            print(f"[Config] Applied opponent's BLUE beetle geometry: {horn_type}")
        else:
            print(f"[Config] Applied opponent's BLUE beetle colors (no geometry change)")
    else:
        # Opponent is guest, so update RED beetle (opponent's beetle)
        # Check if geometry changed (only rebuild if shape parameters changed, not just colors)
        geometry_changed = (
            red_horn_type != horn_type or
            window.red_horn_shaft_value != config['shaft'] or
            window.red_horn_prong_value != config['prong'] or
            window.red_back_body_height_value != config['back_body'] or
            window.red_body_length_value != config['body_len'] or
            window.red_body_width_value != config['body_width'] or
            window.red_leg_length_value != config['leg_len']
        )
        red_horn_type = horn_type
        window.red_horn_shaft_value = config['shaft']
        window.red_horn_prong_value = config['prong']
        window.red_back_body_height_value = config['back_body']
        window.red_body_length_value = config['body_len']
        window.red_body_width_value = config['body_width']
        window.red_leg_length_value = config['leg_len']
        # Apply colors if present (always update colors, no rebuild needed)
        if 'body_color' in config:
            window.red_body_color = config['body_color']
            window.red_leg_color = config['leg_color']
            window.red_leg_tip_color = config['leg_tip_color']
            window.red_stripe_color = config['stripe_color']
            window.red_horn_tip_color = config['horn_tip_color']
            # Update simulation color fields
            simulation.red_body_color[None] = ti.Vector([config['body_color'][0], config['body_color'][1], config['body_color'][2]])
            simulation.red_leg_color[None] = ti.Vector([config['leg_color'][0], config['leg_color'][1], config['leg_color'][2]])
            simulation.red_leg_tip_color[None] = ti.Vector([config['leg_tip_color'][0], config['leg_tip_color'][1], config['leg_tip_color'][2]])
            simulation.red_stripe_color[None] = ti.Vector([config['stripe_color'][0], config['stripe_color'][1], config['stripe_color'][2]])
            simulation.red_horn_tip_color[None] = ti.Vector([config['horn_tip_color'][0], config['horn_tip_color'][1], config['horn_tip_color'][2]])
        # Only rebuild geometry if shape parameters changed (prevents jumping when only colors change)
        if geometry_changed:
            rebuild_red_beetle(
                config['shaft'], config['prong'], 4, config['back_body'],
                config['body_len'], config['body_width'], config['leg_len'],
                horn_type
            )
            print(f"[Config] Applied opponent's RED beetle geometry: {horn_type}")
        else:
            print(f"[Config] Applied opponent's RED beetle colors (no geometry change)")

    return True


