def get_spawn_position(for_blue=True, is_initial=False):
    """Get a valid spawn position based on current arena mode.
    Returns (x, z, rotation) tuple.
    is_initial=True for game start positions, False for respawns."""
    import random

    if donut_mode:
        # Spawn on the donut ring - pick random angle and distance
        angle = random.uniform(0, 2 * math.pi)
        # Spawn in middle of the ring (between inner and outer radius)
        spawn_radius = (DONUT_INNER_RADIUS + DONUT_OUTER_RADIUS) / 2
        x = math.cos(angle) * spawn_radius
        z = math.sin(angle) * spawn_radius
        # Face toward center (or opposite beetle)
        rotation = angle + math.pi  # Face inward
        return (x, z, rotation)
    elif figure8_mode:
        # Spawn at center of respective circle, facing the other circle
        if for_blue:
            return (FIGURE8_LEFT_CENTER_X, 0.0, 0.0)  # Left circle, face right
        else:
            return (FIGURE8_RIGHT_CENTER_X, 0.0, math.pi)  # Right circle, face left
    elif yinyang_mode:
        # Spawn on opposite sides of the ring
        ring_spawn_radius = (YINYANG_INNER_RADIUS + YINYANG_OUTER_RADIUS) / 2  # Middle of ring
        if for_blue:
            return (-ring_spawn_radius, 0.0, 0.0)  # West side, face right
        else:
            return (ring_spawn_radius, 0.0, math.pi)  # East side, face left
    elif hourglass_mode:
        # Spawn at the meatiest part of the hourglass (not too close to edge)
        spawn_x = 18.0  # About 56% out - good width here
        if for_blue:
            return (-spawn_x, 0.0, 0.0)  # Left side, face right
        else:
            return (spawn_x, 0.0, math.pi)  # Right side, face left
    elif square_bridge_mode:
        # Spawn on opposite ends of the long bridge, facing each other
        spawn_x = 20.0  # On the bridge, toward each end
        if for_blue:
            return (-spawn_x, 0.0, 0.0)  # Left end of bridge, face right
        else:
            return (spawn_x, 0.0, math.pi)  # Right end of bridge, face left
    else:
        # Normal arena
        if is_initial:
            # Initial game start positions (spread apart)
            if for_blue:
                return (-20.0, 0.0, 0.0)  # Blue on left, facing right
            else:
                return (20.0, 0.0, math.pi)  # Red on right, facing left
        else:
            # Respawn at center
            if for_blue:
                return (0.0, 0.0, 0.0)  # Center, facing right
            else:
                return (0.0, 0.0, math.pi)  # Center, facing left

