def get_bombardier_rear_position(beetle):
    """Get world position of bombardier's butt (spray origin)

    Accounts for beetle pitch, roll, and yaw rotations.
    """
    # Local position of butt tip (in beetle body coords, facing +X)
    local_x = -9.0  # Rear of beetle
    local_y = -1.0  # Lower to match butt height
    local_z = 0.0   # Centered

    # Apply beetle's full 3D rotation: yaw -> pitch -> roll
    cos_yaw = math.cos(beetle.rotation)
    sin_yaw = math.sin(beetle.rotation)
    cos_pitch = math.cos(beetle.pitch)
    sin_pitch = math.sin(beetle.pitch)
    cos_roll = math.cos(beetle.roll)
    sin_roll = math.sin(beetle.roll)

    # Step 1: Yaw rotation (around Y-axis)
    temp_x = local_x * cos_yaw - local_z * sin_yaw
    temp_z = local_x * sin_yaw + local_z * cos_yaw
    temp_y = local_y

    # Step 2: Pitch rotation (around Z-axis in world space)
    temp2_x = temp_x * cos_pitch - temp_y * sin_pitch
    temp2_y = temp_x * sin_pitch + temp_y * cos_pitch
    temp2_z = temp_z

    # Step 3: Roll rotation (around X-axis in world space)
    final_x = temp2_x
    final_y = temp2_y * cos_roll - temp2_z * sin_roll
    final_z = temp2_y * sin_roll + temp2_z * cos_roll

    # Add beetle world position
    rear_x = beetle.x + final_x
    rear_y = RENDER_Y_OFFSET + beetle.y + final_y
    rear_z = beetle.z + final_z

    return rear_x, rear_y, rear_z

def get_spinneret_position(beetle, spider_aim, body_length):
    """Get world position of spider's spinneret (silk emission point at abdomen tip)

    Accounts for spider_aim (abdomen tilt), body_length, and beetle's world rotation.
    """
    # Local position of spinneret (in beetle body coords, facing +X)
    # Scale with body_length so it stays at the back of the abdomen
    local_x = -body_length + 3.0  # 3 voxels in from tip of abdomen
    local_y = 2.0    # Slightly above center
    local_z = 0.0    # Centered

    # First apply spider aim rotation (abdomen tilts around pedicel pivot)
    # This rotates the spinneret position based on butt aim angle
    aim_angle = spider_aim * SPIDER_AIM_MAX
    cos_aim = math.cos(aim_angle)
    sin_aim = math.sin(aim_angle)
    pivot_x = 3.0  # Pedicel pivot point

    # Rotate around pedicel pivot in X-Y plane
    rel_x = local_x - pivot_x
    rotated_x = pivot_x + rel_x * cos_aim - local_y * sin_aim
    rotated_y = rel_x * sin_aim + local_y * cos_aim
    local_x = rotated_x
    local_y = rotated_y

    # Now apply beetle's full 3D rotation: yaw -> pitch -> roll
    cos_yaw = math.cos(beetle.rotation)
    sin_yaw = math.sin(beetle.rotation)
    cos_pitch = math.cos(beetle.pitch)
    sin_pitch = math.sin(beetle.pitch)
    cos_roll = math.cos(beetle.roll)
    sin_roll = math.sin(beetle.roll)

    # Step 1: Yaw rotation (around Y-axis)
    temp_x = local_x * cos_yaw - local_z * sin_yaw
    temp_z = local_x * sin_yaw + local_z * cos_yaw
    temp_y = local_y

    # Step 2: Pitch rotation (around Z-axis in world space)
    temp2_x = temp_x * cos_pitch - temp_y * sin_pitch
    temp2_y = temp_x * sin_pitch + temp_y * cos_pitch
    temp2_z = temp_z

    # Step 3: Roll rotation (around X-axis in world space)
    final_x = temp2_x
    final_y = temp2_y * cos_roll - temp2_z * sin_roll
    final_z = temp2_y * sin_roll + temp2_z * cos_roll

    # Add beetle world position
    spin_x = beetle.x + final_x
    spin_y = RENDER_Y_OFFSET + beetle.y + final_y
    spin_z = beetle.z + final_z

    return spin_x, spin_y, spin_z

def get_scorpion_tail_tip_position(beetle, body_length, back_body_height):
    """Get world position of scorpion's tail stinger tip (venom origin)

    The tail pivots at the rear of the body and curves up/over the beetle.
    The stinger tip ends up pointing forward when the tail is raised.
    Accounts for beetle pitch, roll, and yaw rotations.
    """
    # Tail geometry constants
    tip_height_at_rest = 11.0  # Height of tip from pivot (tuned to match visual)
    effective_forward = 15.0  # Horizontal reach of tip from pivot (tuned to match visual)

    # Tail pivot in body-local coords (rear of abdomen, at top)
    pivot_local_x = -body_length + 1.0
    pivot_local_y = float(back_body_height)

    # Apply tail rotation to find tip position relative to pivot
    tail_angle_rad = math.radians(beetle.tail_rotation_angle)
    cos_tail = math.cos(tail_angle_rad)
    sin_tail = math.sin(tail_angle_rad)

    rotated_x = effective_forward * cos_tail - tip_height_at_rest * sin_tail
    rotated_y = effective_forward * sin_tail + tip_height_at_rest * cos_tail

    # Tip position in body-local coords (before beetle rotation)
    local_x = pivot_local_x + rotated_x
    local_y = pivot_local_y + rotated_y
    local_z = 0.0  # Tail is centered

    # Apply beetle's full 3D rotation: yaw -> pitch -> roll
    cos_yaw = math.cos(beetle.rotation)
    sin_yaw = math.sin(beetle.rotation)
    cos_pitch = math.cos(beetle.pitch)
    sin_pitch = math.sin(beetle.pitch)
    cos_roll = math.cos(beetle.roll)
    sin_roll = math.sin(beetle.roll)

    # Step 1: Yaw rotation (around Y-axis)
    temp_x = local_x * cos_yaw - local_z * sin_yaw
    temp_z = local_x * sin_yaw + local_z * cos_yaw
    temp_y = local_y

    # Step 2: Pitch rotation (around Z-axis in world space)
    temp2_x = temp_x * cos_pitch - temp_y * sin_pitch
    temp2_y = temp_x * sin_pitch + temp_y * cos_pitch
    temp2_z = temp_z

    # Step 3: Roll rotation (around X-axis in world space)
    final_x = temp2_x
    final_y = temp2_y * cos_roll - temp2_z * sin_roll
    final_z = temp2_y * sin_roll + temp2_z * cos_roll

    # Add beetle world position
    world_x = beetle.x + final_x
    world_y = RENDER_Y_OFFSET + beetle.y + final_y
    world_z = beetle.z + final_z

    return world_x, world_y, world_z

def get_scorpion_venom_direction(beetle):
    """Get direction vector for venom shot from scorpion tail tip.

    The venom shoots forward (toward where the stinger points), which is
    approximately forward from the beetle but angled based on tail position.
    """
    # Venom shoots in the direction the beetle is facing
    # (the stinger tip points forward over the head)
    dir_x = math.cos(beetle.rotation)
    dir_z = math.sin(beetle.rotation)
    return dir_x, dir_z

def process_spray_collisions(target_beetle, target_color, skip_owner):
    """Run GPU kernel to check spray-voxel collisions, then process hits. Returns list of (idx, hit_x, hit_y, hit_z)."""
    # Run GPU collision detection kernel
    check_spray_voxel_collision_kernel(target_color, skip_owner)

    # Collect hits from kernel results
    # OPTIMIZATION: Batch read from GPU with to_numpy() - single sync instead of N syncs
    # (Reading individual elements in a Python loop caused 55ms+ of GPU sync stalls!)
    num_spray = simulation.num_spray[None]
    if num_spray == 0:
        return []

    # Single GPU->CPU transfer for all data
    spray_hit_np = simulation.spray_hit.to_numpy()[:num_spray]
    spray_hit_pos_np = simulation.spray_hit_pos.to_numpy()[:num_spray]

    hits = []
    for idx in range(num_spray):
        if spray_hit_np[idx] == 1:
            pos = spray_hit_pos_np[idx]
            hits.append((idx, pos[0], pos[1], pos[2]))
    return hits

def apply_spray_impact(target_beetle, spray_idx, hit_x, hit_y, hit_z):
    """Push beetle back and spawn explosion when spray hits. Uses hit position for torque/flip physics."""
    spray_vx = simulation.spray_vel[spray_idx][0]
    spray_vy = simulation.spray_vel[spray_idx][1]
    spray_vz = simulation.spray_vel[spray_idx][2]
    spray_color = simulation.spray_color[spray_idx]

    # Detect venom (yellow: R > G) vs bombardier spray (green: G > R)
    is_venom = spray_color[0] > spray_color[1]

    # Calculate push direction (spray velocity direction)
    speed = math.sqrt(spray_vx*spray_vx + spray_vz*spray_vz)
    if speed > 0.1:
        push_dir_x = spray_vx / speed
        push_dir_z = spray_vz / speed
    else:
        # Fallback: push away from beetle center
        dx = target_beetle.x - hit_x
        dz = target_beetle.z - hit_z
        dist = math.sqrt(dx*dx + dz*dz)
        if dist > 0.1:
            push_dir_x = -dx / dist
            push_dir_z = -dz / dist
        else:
            push_dir_x = 0.0
            push_dir_z = 0.0

    # Calculate lever arm from beetle center to hit position
    lever_x = hit_x - target_beetle.x
    lever_y = hit_y - (RENDER_Y_OFFSET + target_beetle.y)  # Y relative to beetle center
    lever_z = hit_z - target_beetle.z

    # Lever distance affects torque magnitude (hits further from center = more spin)
    lever_dist = math.sqrt(lever_x*lever_x + lever_z*lever_z)
    leverage_mult = 1.0 + (lever_dist / 10.0)  # Bonus for off-center hits

    if is_venom:
        # === VENOM: Low push, high lift and flip ===
        # Minimal horizontal push (venom destabilizes, doesn't push)
        push_force = SPRAY_PUSH_FORCE * 0.15 * leverage_mult
        target_beetle.vx += push_dir_x * push_force
        target_beetle.vz += push_dir_z * push_force

        # Minimal vertical lift
        target_beetle.vy += 0.05 * leverage_mult

        # Strong flip strength (independent of lift)
        flip_strength = 40.0 * leverage_mult

        # Strong pitch torque (flip forward/backward)
        pitch_torque = lever_z * flip_strength
        target_beetle.pitch_velocity += pitch_torque / target_beetle.pitch_inertia

        # Strong roll torque (flip side to side)
        roll_torque = lever_x * flip_strength
        target_beetle.roll_velocity += roll_torque / target_beetle.roll_inertia

        # Moderate yaw spin
        yaw_torque = (lever_x * push_dir_z - lever_z * push_dir_x) * flip_strength * 0.02
        target_beetle.angular_velocity += yaw_torque / target_beetle.moment_of_inertia
    else:
        # === BOMBARDIER SPRAY: Strong push, moderate flip ===
        # Strong horizontal push
        push_force = SPRAY_PUSH_FORCE * leverage_mult
        target_beetle.vx += push_dir_x * push_force
        target_beetle.vz += push_dir_z * push_force

        # Yaw torque (horizontal spin)
        yaw_torque = (lever_x * push_dir_z - lever_z * push_dir_x) * push_force * 0.15
        target_beetle.angular_velocity += yaw_torque / target_beetle.moment_of_inertia

        # Vertical lift (based on spray's vertical velocity)
        lift_force = max(0.0, spray_vy * 0.3) * leverage_mult
        target_beetle.vy += lift_force + 3.0

        # Pitch torque (nose up/down)
        pitch_torque = lever_z * lift_force * 2.0
        target_beetle.pitch_velocity += pitch_torque / target_beetle.pitch_inertia

        # Roll torque (side-to-side tilt)
        roll_torque = lever_x * lift_force * 2.0
        target_beetle.roll_velocity += roll_torque / target_beetle.roll_inertia

    # Spawn mini explosion at hit position with spray's color
    spawn_spray_explosion(hit_x, hit_y, hit_z, spray_color[0], spray_color[1], spray_color[2])

    # Kill the spray particle
    simulation.spray_lifetime[spray_idx] = 0

def check_spray_ball_collision():
    """Check if any spray particles hit the ball and apply impact."""
    if not beetle_ball.active:
        return

    ball_x = beetle_ball.x
    ball_y = beetle_ball.y + RENDER_Y_OFFSET  # Convert to render space
    ball_z = beetle_ball.z
    ball_radius = beetle_ball.radius
    hit_radius = ball_radius + 2.0

    num_spray = simulation.num_spray[None]
    if num_spray == 0:
        return

    # OPTIMIZATION: Batch read from GPU with to_numpy() - single sync instead of N syncs
    spray_active_np = simulation.spray_active.to_numpy()[:num_spray]
    spray_lifetime_np = simulation.spray_lifetime.to_numpy()[:num_spray]
    spray_pos_np = simulation.spray_pos.to_numpy()[:num_spray]
    spray_vel_np = simulation.spray_vel.to_numpy()[:num_spray]
    spray_color_np = simulation.spray_color.to_numpy()[:num_spray]

    hits_to_process = []  # Collect hits, process after loop to avoid GPU writes during iteration

    for idx in range(num_spray):
        # Skip inactive particles (free list pattern)
        if spray_active_np[idx] == 0:
            continue
        # Grace period - skip very fresh particles (first ~0.1 sec)
        if spray_lifetime_np[idx] > 1.7:
            continue

        pos = spray_pos_np[idx]
        vel = spray_vel_np[idx]

        # Distance check (sphere collision)
        dx = pos[0] - ball_x
        dy = pos[1] - ball_y
        dz = pos[2] - ball_z
        dist = math.sqrt(dx*dx + dy*dy + dz*dz)

        if dist < hit_radius:  # Hit!
            color = spray_color_np[idx]
            hits_to_process.append((idx, pos, vel, dist, dx, dy, dz, color))

    # Process hits (now safe to write to GPU)
    for idx, pos, vel, dist, dx, dy, dz, color in hits_to_process:
        # Get spray direction for push
        spray_speed = math.sqrt(vel[0]**2 + vel[1]**2 + vel[2]**2)
        if spray_speed > 0.1:
            push_x = vel[0] / spray_speed
            push_y = vel[1] / spray_speed
            push_z = vel[2] / spray_speed
        else:
            if dist > 0.1:
                push_x, push_y, push_z = dx / dist, dy / dist, dz / dist
            else:
                push_x, push_y, push_z = 1.0, 0.0, 0.0

        # Apply push to ball
        push_force = SPRAY_PUSH_FORCE * 0.8  # Slightly less than beetle push
        beetle_ball.vx += push_x * push_force
        beetle_ball.vy += push_y * push_force * 0.3  # Less vertical
        beetle_ball.vz += push_z * push_force

        # Add spin from impact (consistent with beetle collision physics)
        spin_strength = push_force * 0.1
        beetle_ball.angular_velocity += push_z * spin_strength  # Yaw from z-push
        beetle_ball.pitch_velocity += push_x * spin_strength    # Pitch from x-push
        beetle_ball.roll_velocity += push_y * spin_strength     # Roll from y-push

        # Spawn explosion and kill spray (use spray's color)
        spawn_spray_explosion(pos[0], pos[1], pos[2], color[0], color[1], color[2])
        simulation.spray_lifetime[idx] = 0

