@ti.kernel
def spawn_spray_burst(origin_x: ti.f32, origin_y: ti.f32, origin_z: ti.f32,
                      dir_x: ti.f32, dir_z: ti.f32,
                      angle_offset: ti.f32,
                      speed: ti.f32,
                      owner: ti.i32,
                      num_particles: ti.i32,
                      aim_y: ti.f32,
                      lifetime: ti.f32,
                      color_r: ti.f32, color_g: ti.f32, color_b: ti.f32):
    """Spawn spray particles in cone from origin point

    Args:
        aim_y: Vertical velocity component based on aim angle (positive = up, negative = down)
        lifetime: Base lifetime for particles (actual = lifetime + random * 0.3)
        color_r, color_g, color_b: Base RGB color for particles
    """
    for i in range(num_particles):
        idx = ti.atomic_add(simulation.num_spray[None], 1)
        if idx < simulation.MAX_SPRAY:
            simulation.spray_active[idx] = 1  # Mark slot as active (free list pattern)
            ti.atomic_add(simulation.spray_active_count[None], 1)  # Track live count
            # Apply angle offset to direction (rotate direction by angle_offset)
            cos_a = ti.cos(angle_offset)
            sin_a = ti.sin(angle_offset)
            rotated_x = dir_x * cos_a - dir_z * sin_a
            rotated_z = dir_x * sin_a + dir_z * cos_a

            # Add small random spread (±5°)
            spread = (ti.random() - 0.5) * 0.17  # ~10° total spread
            cos_s = ti.cos(spread)
            sin_s = ti.sin(spread)
            final_x = rotated_x * cos_s - rotated_z * sin_s
            final_z = rotated_x * sin_s + rotated_z * cos_s

            particle_speed = speed * (0.9 + ti.random() * 0.2)

            # Slight random offset at spawn point for natural spray pattern
            spawn_offset_x = (ti.random() - 0.5) * 2.0
            spawn_offset_z = (ti.random() - 0.5) * 2.0

            simulation.spray_pos[idx] = ti.math.vec3(origin_x + spawn_offset_x,
                                                      origin_y + ti.random() * 1.0,
                                                      origin_z + spawn_offset_z)
            simulation.spray_vel[idx] = ti.math.vec3(final_x * particle_speed,
                                                      15.0 + aim_y + ti.random() * 5.0,  # Upward arc + 2deg base offset + aim adjustment
                                                      final_z * particle_speed)
            # Apply color with slight variation
            color_var = 0.9 + ti.random() * 0.2
            simulation.spray_color[idx] = ti.math.vec3(color_r * color_var, color_g * color_var, color_b * color_var)
            simulation.spray_lifetime[idx] = lifetime + ti.random() * 0.3
            simulation.spray_owner[idx] = owner

@ti.kernel
def update_spray_particles(dt: ti.f32):
    """Update spray positions and apply gravity, with ground collision inside arena

    Uses free list pattern: loops over all slots, skips inactive ones.
    Dead particles marked inactive (not compacted) for GPU parallelism.
    Caps iteration to MAX_SPRAY_CHECK to prevent high water mark from tanking FPS.
    """
    # Cap iteration to prevent performance spiral when high water mark grows
    check_count = ti.min(simulation.num_spray[None], simulation.MAX_SPRAY_CHECK)

    for idx in range(check_count):
        # Skip inactive particles (free list pattern - no compaction needed)
        if simulation.spray_active[idx] == 0:
            continue

        simulation.spray_lifetime[idx] -= dt

        # Mark dead particles as inactive
        if simulation.spray_lifetime[idx] <= 0:
            simulation.spray_active[idx] = 0
            ti.atomic_sub(simulation.spray_active_count[None], 1)  # Track live count
            continue

        simulation.spray_vel[idx].y -= 15.0 * dt  # Light gravity
        simulation.spray_pos[idx] += simulation.spray_vel[idx] * dt

        # Ground collision - only inside arena, particles can fall off edge
        pos = simulation.spray_pos[idx]
        dist_from_center = ti.sqrt(pos.x * pos.x + pos.z * pos.z)
        ground_y = RENDER_Y_OFFSET  # 33.0 - ground level in grid space

        if pos.y < ground_y and dist_from_center < ARENA_RADIUS:
            # Inside arena - stop at ground level
            simulation.spray_pos[idx].y = ground_y
            simulation.spray_vel[idx].y = 0.0
            # Reduce horizontal velocity (friction/splat)
            simulation.spray_vel[idx].x *= 0.3
            simulation.spray_vel[idx].z *= 0.3

@ti.kernel
def cleanup_dead_spray():
    """Remove expired spray particles by compacting array (serial due to compaction)"""
    write_idx = 0

    ti.loop_config(serialize=True)
    for read_idx in range(simulation.num_spray[None]):
        # Check both lifetime AND active flag (free list pattern)
        if simulation.spray_lifetime[read_idx] > 0.0 and simulation.spray_active[read_idx] == 1:
            # Particle still alive, keep it
            if write_idx != read_idx:
                simulation.spray_pos[write_idx] = simulation.spray_pos[read_idx]
                simulation.spray_vel[write_idx] = simulation.spray_vel[read_idx]
                simulation.spray_color[write_idx] = simulation.spray_color[read_idx]
                simulation.spray_lifetime[write_idx] = simulation.spray_lifetime[read_idx]
                simulation.spray_owner[write_idx] = simulation.spray_owner[read_idx]
                simulation.spray_active[write_idx] = 1  # Mark compacted slot as active
            write_idx += 1

    simulation.num_spray[None] = write_idx

