@ti.func
def transform_body_voxel_to_world(
    voxel_idx: ti.i32,
    is_blue: ti.i32,
    world_x: ti.f32, world_y: ti.f32, world_z: ti.f32,
    rotation: ti.f32, pitch: ti.f32, roll: ti.f32,
    horn_pitch: ti.f32, horn_yaw: ti.f32, tail_pitch: ti.f32,
    horn_type_id: ti.i32, body_length: ti.i32, back_body_height: ti.i32,
    spray_aim_pitch: ti.f32, spider_aim_pitch: ti.f32,
    default_horn_pitch: ti.f32
) -> ti.math.vec3:
    """Transform a body cache voxel to world position - mirrors place_animated_beetle logic exactly"""

    # Load local coordinates from appropriate cache
    local_x = 0.0
    local_y = 0
    local_z = 0.0

    if is_blue == 1:
        local_x = float(blue_body_cache_x[voxel_idx])
        local_y = blue_body_cache_y[voxel_idx]
        local_z = float(blue_body_cache_z[voxel_idx])
    else:
        local_x = float(red_body_cache_x[voxel_idx])
        local_y = red_body_cache_y[voxel_idx]
        local_z = float(red_body_cache_z[voxel_idx])

    # Store original values for zone detection
    orig_local_x = local_x
    orig_local_y = local_y
    orig_local_z = local_z

    # Pre-calculate trig values
    cos_yaw = ti.cos(rotation)
    sin_yaw = ti.sin(rotation)
    cos_pitch_body = ti.cos(pitch)
    sin_pitch_body = ti.sin(pitch)
    cos_roll = ti.cos(roll)
    sin_roll = ti.sin(roll)
    cos_horn_pitch = ti.cos(horn_pitch)
    sin_horn_pitch = ti.sin(horn_pitch)
    cos_horn_yaw = ti.cos(horn_yaw)
    sin_horn_yaw = ti.sin(horn_yaw)

    # Scorpion-specific: pitch deviation from default
    pitch_deviation = horn_pitch - default_horn_pitch
    cos_default = ti.cos(default_horn_pitch)
    sin_default = ti.sin(default_horn_pitch)
    cos_deviation = ti.cos(pitch_deviation)
    sin_deviation = ti.sin(pitch_deviation)

    # Horn pivot (scorpion claws at x=2, others at x=3)
    horn_pivot_x = 2.0 if horn_type_id == 3 else 3.0
    horn_pivot_y = 2

    # Detect if this is a horn voxel that needs rotation
    should_rotate = False

    if horn_type_id == 3:  # Scorpion - rotate claws (dx >= 2 AND |dz| > 2 to exclude tail)
        should_rotate = orig_local_x >= 2.0 and ti.abs(orig_local_z) > 2.0
    elif horn_type_id == 4:  # Atlas - only cephalic horn (center, |z| <= 1.5)
        should_rotate = orig_local_x >= 3.0 and ti.abs(orig_local_z) <= 1.5
    elif horn_type_id == 6:  # Spider - no horn rotation
        should_rotate = False
    elif orig_local_x >= 3.0:  # Other beetles - rotate horns
        should_rotate = True

    if should_rotate:
        rel_x = local_x - horn_pivot_x
        rel_y = float(local_y - horn_pivot_y)
        rel_z = local_z

        # Initialize pitched results
        pitched_x = rel_x
        pitched_y = rel_y
        pitched_z = rel_z

        # STEP 1: Pitch rotation - differs by beetle type
        if horn_type_id == 3:
            # SCORPION: Both claws start at default angle, then alternate when R/Y pressed
            temp_x = rel_x * cos_default - rel_y * sin_default
            temp_y = rel_x * sin_default + rel_y * cos_default

            if pitch_deviation != 0.0:
                if rel_z < -1.0:  # Left claw - invert deviation
                    pitched_x = temp_x * cos_deviation + temp_y * sin_deviation
                    pitched_y = -temp_x * sin_deviation + temp_y * cos_deviation
                elif rel_z > 1.0:  # Right claw - normal deviation
                    pitched_x = temp_x * cos_deviation - temp_y * sin_deviation
                    pitched_y = temp_x * sin_deviation + temp_y * cos_deviation
                else:
                    pitched_x = temp_x
                    pitched_y = temp_y
            else:
                pitched_x = temp_x
                pitched_y = temp_y

        elif horn_type_id == 2:
            # HERCULES: Only bottom horn rotates (y < 5), top horn stays fixed
            if orig_local_y < 5:
                pitched_x = rel_x * cos_horn_pitch - rel_y * sin_horn_pitch
                pitched_y = rel_x * sin_horn_pitch + rel_y * cos_horn_pitch
            elif orig_local_y < 8 and rel_x >= 10.0:
                # Mid-height but far forward - bottom horn tip
                pitched_x = rel_x * cos_horn_pitch - rel_y * sin_horn_pitch
                pitched_y = rel_x * sin_horn_pitch + rel_y * cos_horn_pitch
            # else: top horn stays fixed (pitched = rel)

        else:
            # STAG/RHINO/ATLAS: Rotate entire horn
            pitched_x = rel_x * cos_horn_pitch - rel_y * sin_horn_pitch
            pitched_y = rel_x * sin_horn_pitch + rel_y * cos_horn_pitch

        pitched_z = rel_z

        # STEP 2: Yaw rotation - differs by beetle type
        yawed_x = pitched_x
        yawed_y = pitched_y
        yawed_z = pitched_z

        if horn_type_id == 1:
            # STAG: Opposite rotations for left vs right pincers
            if pitched_z < -0.1:  # Left pincer
                yawed_x = pitched_x * cos_horn_yaw + pitched_z * sin_horn_yaw
                yawed_z = -pitched_x * sin_horn_yaw + pitched_z * cos_horn_yaw
            elif pitched_z > 0.1:  # Right pincer - inverse
                yawed_x = pitched_x * cos_horn_yaw - pitched_z * sin_horn_yaw
                yawed_z = pitched_x * sin_horn_yaw + pitched_z * cos_horn_yaw
            # else: center voxels don't rotate

        elif horn_type_id == 2:
            # HERCULES: Roll/twist around X-axis (not yaw)
            yawed_x = pitched_x
            yawed_y = pitched_y * cos_horn_yaw - pitched_z * sin_horn_yaw
            yawed_z = pitched_y * sin_horn_yaw + pitched_z * cos_horn_yaw

        elif horn_type_id == 3:
            # SCORPION: No yaw for claws (already handled in pitch)
            pass

        else:
            # RHINO/ATLAS: Standard yaw rotation
            yawed_x = pitched_x * cos_horn_yaw + pitched_z * sin_horn_yaw
            yawed_z = -pitched_x * sin_horn_yaw + pitched_z * cos_horn_yaw

        # Translate back from pivot
        local_x = yawed_x + horn_pivot_x
        local_y = int(ti.round(yawed_y + float(horn_pivot_y)))
        local_z = yawed_z

    # SCORPION TAIL ROTATION
    if horn_type_id == 3:
        is_tail = (orig_local_x >= -body_length) and (orig_local_x <= -body_length + 30) and (orig_local_y >= back_body_height + 3) and (ti.abs(orig_local_z) <= 2)
        if is_tail:
            tail_pivot_x = float(-body_length + 1)
            tail_pivot_y = float(back_body_height)
            tail_rel_x = local_x - tail_pivot_x
            tail_rel_y = float(local_y) - tail_pivot_y
            cos_tail = ti.cos(tail_pitch)
            sin_tail = ti.sin(tail_pitch)
            local_x = tail_pivot_x + tail_rel_x * cos_tail - tail_rel_y * sin_tail
            local_y = int(ti.round(tail_pivot_y + tail_rel_x * sin_tail + tail_rel_y * cos_tail))

    # BOMBARDIER AIM ROTATION
    if horn_type_id == 5 and spray_aim_pitch != 0.0:
        rear_pivot_x = float(-body_length)
        cos_aim = ti.cos(spray_aim_pitch)
        sin_aim = ti.sin(spray_aim_pitch)
        rel_x = local_x - rear_pivot_x
        ly_aim = float(local_y)
        local_x = rear_pivot_x + rel_x * cos_aim - ly_aim * sin_aim
        local_y = int(ti.round(rel_x * sin_aim + ly_aim * cos_aim))

    # SPIDER ABDOMEN ROTATION
    if horn_type_id == 6 and spider_aim_pitch != 0.0:
        spider_pivot_x = 3.0
        if orig_local_x < spider_pivot_x:
            cos_spider = ti.cos(spider_aim_pitch)
            sin_spider = ti.sin(spider_aim_pitch)
            rel_x = local_x - spider_pivot_x
            ly_spider = float(local_y)
            local_x = spider_pivot_x + rel_x * cos_spider - ly_spider * sin_spider
            local_y = int(ti.round(rel_x * sin_spider + ly_spider * cos_spider))

    # Apply beetle 3D rotation (yaw -> pitch -> roll)
    ly = float(local_y)
    temp_x = local_x * cos_yaw - local_z * sin_yaw
    temp_z = local_x * sin_yaw + local_z * cos_yaw
    temp_y = ly

    temp2_x = temp_x * cos_pitch_body - temp_y * sin_pitch_body
    temp2_y = temp_x * sin_pitch_body + temp_y * cos_pitch_body
    temp2_z = temp_z

    final_x = temp2_x
    final_y = temp2_y * cos_roll - temp2_z * sin_roll
    final_z = temp2_y * sin_roll + temp2_z * cos_roll

    # Return world position
    return ti.math.vec3(world_x + final_x, world_y + RENDER_Y_OFFSET + final_y, world_z + final_z)


@ti.func
def is_horn_zone_voxel(voxel_idx: ti.i32, is_blue: ti.i32, horn_type_id: ti.i32, body_length: ti.i32, back_body_height: ti.i32) -> ti.i32:
    """Check if a voxel is in the horn zone (front) vs body zone"""
    local_x = 0.0
    local_y = 0
    local_z = 0.0

    if is_blue == 1:
        local_x = float(blue_body_cache_x[voxel_idx])
        local_y = blue_body_cache_y[voxel_idx]
        local_z = float(blue_body_cache_z[voxel_idx])
    else:
        local_x = float(red_body_cache_x[voxel_idx])
        local_y = red_body_cache_y[voxel_idx]
        local_z = float(red_body_cache_z[voxel_idx])

    is_horn = 0

    if horn_type_id == 3:  # Scorpion - claws and tail are "horn"
        if local_x >= 2.0 and ti.abs(local_z) > 2.0:  # Claws
            is_horn = 1
        elif local_y >= back_body_height + 3 and ti.abs(local_z) <= 2:  # Tail
            is_horn = 1
    elif horn_type_id == 6:  # Spider - no horn zone
        is_horn = 0
    elif local_x >= 3.0:  # Other beetles - front is horn
        is_horn = 1

    return is_horn


@ti.kernel
def spawn_silk(origin_x: ti.f32, origin_y: ti.f32, origin_z: ti.f32,
               dir_x: ti.f32, dir_z: ti.f32,
               speed: ti.f32, aim_y: ti.f32,
               owner: ti.i32, spiral_phase: ti.f32):
    """Spawn single silk particle in elegant expanding spiral pattern"""
    idx = ti.atomic_add(simulation.num_silk[None], 1)
    if idx < simulation.MAX_SILK:
        simulation.silk_active[idx] = 1  # Mark slot as active (free list pattern)
        ti.atomic_add(simulation.silk_active_count[None], 1)  # Track live count
        # Tight starting spiral radius (expands via tangential velocity)
        spiral_radius = 0.3

        # Position on spiral determined by phase
        # Perpendicular vectors to firing direction (backwards)
        perp_x = -dir_z
        perp_z = dir_x

        # Spiral offset in local space
        cos_phase = ti.cos(spiral_phase)
        sin_phase = ti.sin(spiral_phase)
        offset_x = perp_x * cos_phase * spiral_radius
        offset_z = perp_z * cos_phase * spiral_radius
        offset_y = sin_phase * spiral_radius

        simulation.silk_pos[idx] = ti.math.vec3(
            origin_x + offset_x,
            origin_y + offset_y,
            origin_z + offset_z
        )

        # Main velocity backwards + tangential for expanding spiral
        # Tangential velocity makes spiral grow as it travels
        tangent_strength = 2.5  # How fast spiral expands
        tangent_x = perp_x * (-sin_phase) * tangent_strength
        tangent_z = perp_z * (-sin_phase) * tangent_strength
        tangent_y = cos_phase * tangent_strength

        simulation.silk_vel[idx] = ti.math.vec3(
            dir_x * speed + tangent_x,
            aim_y + 5.0 + tangent_y,  # Slight upward arc
            dir_z * speed + tangent_z
        )

        # Cream/off-white silk color
        simulation.silk_color[idx] = ti.math.vec3(
            0.95,
            0.92,
            0.85
        )

        simulation.silk_lifetime[idx] = SILK_LIFETIME_FLYING
        simulation.silk_owner[idx] = owner
        simulation.silk_stuck[idx] = 0  # Flying
        # Initialize beetle-sticking fields
        simulation.silk_stuck_beetle[idx] = -1  # Not stuck to any beetle
        simulation.silk_stuck_voxel_idx[idx] = 0
        simulation.silk_stuck_offset[idx] = ti.math.vec3(0.0, 0.0, 0.0)

@ti.func
def silk_pos_to_grid(x: ti.f32, z: ti.f32) -> ti.math.ivec2:
    """Convert world position to grid cell (arena center is at 0,0)"""
    # Arena spans -32 to +32, grid is 0 to 63
    gx = int((x + 32.0) / simulation.SILK_CELL_SIZE)
    gz = int((z + 32.0) / simulation.SILK_CELL_SIZE)
    # Clamp to grid bounds
    gx = ti.max(0, ti.min(simulation.SILK_GRID_SIZE - 1, gx))
    gz = ti.max(0, ti.min(simulation.SILK_GRID_SIZE - 1, gz))
    return ti.math.ivec2(gx, gz)

@ti.kernel
def build_silk_spatial_grid():
    """Build spatial grid from floor-stuck silk for O(1) neighbor queries"""
    # Clear grid counts
    for i, j in simulation.silk_grid_count:
        simulation.silk_grid_count[i, j] = 0

    # Insert floor-stuck silk into grid
    for idx in range(simulation.num_silk[None]):
        # Skip inactive particles (free list pattern)
        if simulation.silk_active[idx] == 0:
            continue
        if simulation.silk_stuck[idx] == 1:  # Floor-stuck only
            pos = simulation.silk_pos[idx]
            cell = silk_pos_to_grid(pos.x, pos.z)
            # Atomically add to cell
            slot = ti.atomic_add(simulation.silk_grid_count[cell.x, cell.y], 1)
            if slot < simulation.SILK_MAX_PER_CELL:
                simulation.silk_grid_particles[cell.x, cell.y, slot] = idx

@ti.func
def check_silk_nearby_grid(x: ti.f32, z: ti.f32, min_dist_sq: ti.f32) -> ti.i32:
    """Check if there's floor silk within min_dist using spatial grid. Returns 1 if collision."""
    cell = silk_pos_to_grid(x, z)
    collision = 0

    # Check 3x3 neighborhood of cells
    for di in ti.static(range(-1, 2)):
        for dj in ti.static(range(-1, 2)):
            ni = cell.x + di
            nj = cell.y + dj
            # Bounds check
            if 0 <= ni < simulation.SILK_GRID_SIZE and 0 <= nj < simulation.SILK_GRID_SIZE:
                # Check all silk in this cell (cap to prevent overflow)
                count = ti.min(simulation.silk_grid_count[ni, nj], simulation.SILK_MAX_PER_CELL)
                for k in range(count):
                    other_idx = simulation.silk_grid_particles[ni, nj, k]
                    other_pos = simulation.silk_pos[other_idx]
                    dx = x - other_pos.x
                    dz = z - other_pos.z
                    if dx * dx + dz * dz < min_dist_sq:
                        collision = 1
    return collision

@ti.kernel
def update_silk_particles(dt: ti.f32):
    """Update silk positions, apply gravity, stick to floor

    Uses free list pattern: loops over all slots, skips inactive ones.
    Dead particles marked inactive (not compacted) for GPU parallelism.
    Caps iteration to MAX_SILK_CHECK to prevent high water mark from tanking FPS.
    """
    # Cap iteration to prevent performance spiral when high water mark grows
    check_count = ti.min(simulation.num_silk[None], simulation.MAX_SILK_CHECK)

    for idx in range(check_count):
        # Skip inactive particles (free list pattern - no compaction needed)
        if simulation.silk_active[idx] == 0:
            continue

        # Decrement lifetime first
        simulation.silk_lifetime[idx] -= dt

        # Mark dead particles as inactive and update counters
        if simulation.silk_lifetime[idx] <= 0:
            # Decrement counter if it was stuck to something (moved from cleanup function)
            if simulation.silk_stuck[idx] == 2:  # Was stuck to beetle
                if simulation.silk_stuck_beetle[idx] == 0:
                    ti.atomic_sub(simulation.silk_on_blue[None], 1)
                elif simulation.silk_stuck_beetle[idx] == 1:
                    ti.atomic_sub(simulation.silk_on_red[None], 1)
            elif simulation.silk_stuck[idx] == 3:  # Was stuck to ball
                ti.atomic_sub(simulation.silk_on_ball[None], 1)
            simulation.silk_active[idx] = 0
            ti.atomic_sub(simulation.silk_active_count[None], 1)  # Track live count
            continue

        if simulation.silk_stuck[idx] == 0:  # Flying
            # Heavier gravity than spray (silk is denser)
            simulation.silk_vel[idx].y -= SILK_GRAVITY * dt
            simulation.silk_pos[idx] += simulation.silk_vel[idx] * dt

            # Floor collision - STICK instead of bounce
            pos = simulation.silk_pos[idx]
            dist_from_center = ti.sqrt(pos.x * pos.x + pos.z * pos.z)

            # Check floor_height_cache to see if there's actually floor at this position
            # (handles holes in donut, yin-yang, figure-8, x-stage modes)
            grid_x = ti.cast(pos.x + 64.0, ti.i32)
            grid_z = ti.cast(pos.z + 64.0, ti.i32)
            grid_x = ti.max(0, ti.min(127, grid_x))
            grid_z = ti.max(0, ti.min(127, grid_z))
            floor_y = floor_height_cache[grid_x, grid_z]
            has_floor = floor_y > -100.0  # -1000 means no floor, valid floor is around 0

            if pos.y < RENDER_Y_OFFSET and has_floor:
                # Check if there's already floor silk nearby using spatial grid (O(1) instead of O(n²))
                MIN_FLOOR_SPACING = 0.5  # Minimum distance between floor silk
                MIN_FLOOR_SPACING_SQ = MIN_FLOOR_SPACING * MIN_FLOOR_SPACING
                has_collision = check_silk_nearby_grid(pos.x, pos.z, MIN_FLOOR_SPACING_SQ)

                if has_collision == 0:
                    # Hit floor inside arena - stick!
                    simulation.silk_pos[idx].y = RENDER_Y_OFFSET
                    simulation.silk_vel[idx] = ti.math.vec3(0.0, 0.0, 0.0)
                    simulation.silk_stuck[idx] = 1
                    simulation.silk_lifetime[idx] = SILK_LIFETIME_STUCK  # Extended lifetime when stuck
                else:
                    # Too close to existing silk - expire quickly
                    simulation.silk_lifetime[idx] = 0.0


@ti.kernel
def check_silk_beetle_collision(
    # Blue beetle state
    blue_x: ti.f32, blue_y: ti.f32, blue_z: ti.f32,
    blue_rotation: ti.f32, blue_pitch: ti.f32, blue_roll: ti.f32,
    blue_horn_pitch: ti.f32, blue_horn_yaw: ti.f32, blue_tail_pitch: ti.f32,
    blue_horn_type_id: ti.i32, blue_body_length: ti.i32, blue_back_height: ti.i32,
    blue_spray_aim: ti.f32, blue_spider_aim: ti.f32, blue_default_horn_pitch: ti.f32, blue_active: ti.i32,
    # Red beetle state
    red_x: ti.f32, red_y: ti.f32, red_z: ti.f32,
    red_rotation: ti.f32, red_pitch: ti.f32, red_roll: ti.f32,
    red_horn_pitch: ti.f32, red_horn_yaw: ti.f32, red_tail_pitch: ti.f32,
    red_horn_type_id: ti.i32, red_body_length: ti.i32, red_back_height: ti.i32,
    red_spray_aim: ti.f32, red_spider_aim: ti.f32, red_default_horn_pitch: ti.f32, red_active: ti.i32
):
    """Check flying silk against beetle voxels and stick if hit"""
    COLLISION_RADIUS = 18.0  # Bounding sphere for fast rejection
    VOXEL_HIT_DIST = 1.5  # Distance to count as hit

    for idx in range(simulation.num_silk[None]):
        # Skip inactive particles (free list pattern)
        if simulation.silk_active[idx] == 0:
            continue
        if simulation.silk_stuck[idx] != 0:  # Only check flying silk
            continue

        pos = simulation.silk_pos[idx]
        owner = simulation.silk_owner[idx]

        # Check blue beetle (if silk not from blue)
        if blue_active == 1 and owner != 0:
            dx = pos.x - blue_x
            dy = pos.y - (blue_y + RENDER_Y_OFFSET)
            dz = pos.z - blue_z
            dist_sq = dx * dx + dy * dy + dz * dz

            if dist_sq < COLLISION_RADIUS * COLLISION_RADIUS:
                # Within bounding sphere - check voxels
                best_dist = 999.0
                best_voxel = -1

                for vi in range(blue_body_cache_size[None]):
                    if best_dist > 0.5:  # Early exit once close enough
                        voxel_world = transform_body_voxel_to_world(
                            vi, 1,  # is_blue = 1
                            blue_x, blue_y, blue_z,
                            blue_rotation, blue_pitch, blue_roll,
                            blue_horn_pitch, blue_horn_yaw, blue_tail_pitch,
                            blue_horn_type_id, blue_body_length, blue_back_height,
                            blue_spray_aim, blue_spider_aim, blue_default_horn_pitch
                        )

                        vdx = pos.x - voxel_world.x
                        vdy = pos.y - voxel_world.y
                        vdz = pos.z - voxel_world.z
                        vdist = ti.sqrt(vdx * vdx + vdy * vdy + vdz * vdz)

                        if vdist < best_dist:
                            best_dist = vdist
                            best_voxel = vi

                if best_dist < VOXEL_HIT_DIST and best_voxel >= 0:
                    # Check if this voxel already has silk (prevent stacking)
                    voxel_taken = False
                    for other in range(simulation.num_silk[None]):
                        if other != idx and simulation.silk_stuck[other] == 2:  # Beetle-stuck
                            if simulation.silk_stuck_beetle[other] == 0:  # On blue beetle
                                if simulation.silk_stuck_voxel_idx[other] == best_voxel:
                                    voxel_taken = True
                                    break

                    if not voxel_taken:
                        # Hit! Stick to this voxel (body or horn)
                        simulation.silk_stuck[idx] = 2  # Stuck to beetle
                        simulation.silk_stuck_beetle[idx] = 0  # Blue beetle
                        simulation.silk_stuck_voxel_idx[idx] = best_voxel
                        simulation.silk_stuck_offset[idx] = ti.math.vec3(
                            (ti.random() - 0.5) * 0.3,
                            (ti.random() - 0.5) * 0.3,
                            (ti.random() - 0.5) * 0.3
                        )
                        simulation.silk_vel[idx] = ti.math.vec3(0.0, 0.0, 0.0)
                        simulation.silk_lifetime[idx] = SILK_LIFETIME_STUCK
                        ti.atomic_add(simulation.silk_on_blue[None], 1)  # Increment counter
                        continue  # Don't check red if already hit blue
                    else:
                        # Voxel already has silk - expire this particle
                        simulation.silk_lifetime[idx] = 0.0
                        continue

        # Check red beetle (if silk not from red)
        if red_active == 1 and owner != 1:
            dx = pos.x - red_x
            dy = pos.y - (red_y + RENDER_Y_OFFSET)
            dz = pos.z - red_z
            dist_sq = dx * dx + dy * dy + dz * dz

            if dist_sq < COLLISION_RADIUS * COLLISION_RADIUS:
                # Within bounding sphere - check voxels
                best_dist = 999.0
                best_voxel = -1

                for vi in range(red_body_cache_size[None]):
                    if best_dist > 0.5:  # Early exit once close enough
                        voxel_world = transform_body_voxel_to_world(
                            vi, 0,  # is_blue = 0
                            red_x, red_y, red_z,
                            red_rotation, red_pitch, red_roll,
                            red_horn_pitch, red_horn_yaw, red_tail_pitch,
                            red_horn_type_id, red_body_length, red_back_height,
                            red_spray_aim, red_spider_aim, red_default_horn_pitch
                        )

                        vdx = pos.x - voxel_world.x
                        vdy = pos.y - voxel_world.y
                        vdz = pos.z - voxel_world.z
                        vdist = ti.sqrt(vdx * vdx + vdy * vdy + vdz * vdz)

                        if vdist < best_dist:
                            best_dist = vdist
                            best_voxel = vi

                if best_dist < VOXEL_HIT_DIST and best_voxel >= 0:
                    # Check if this voxel already has silk (prevent stacking)
                    voxel_taken = False
                    for other in range(simulation.num_silk[None]):
                        if other != idx and simulation.silk_stuck[other] == 2:  # Beetle-stuck
                            if simulation.silk_stuck_beetle[other] == 1:  # On red beetle
                                if simulation.silk_stuck_voxel_idx[other] == best_voxel:
                                    voxel_taken = True
                                    break

                    if not voxel_taken:
                        # Hit! Stick to this voxel (body or horn)
                        simulation.silk_stuck[idx] = 2  # Stuck to beetle
                        simulation.silk_stuck_beetle[idx] = 1  # Red beetle
                        simulation.silk_stuck_voxel_idx[idx] = best_voxel
                        simulation.silk_stuck_offset[idx] = ti.math.vec3(
                            (ti.random() - 0.5) * 0.3,
                            (ti.random() - 0.5) * 0.3,
                            (ti.random() - 0.5) * 0.3
                        )
                        simulation.silk_vel[idx] = ti.math.vec3(0.0, 0.0, 0.0)
                        simulation.silk_lifetime[idx] = SILK_LIFETIME_STUCK
                        ti.atomic_add(simulation.silk_on_red[None], 1)  # Increment counter
                    else:
                        # Voxel already has silk - expire this particle
                        simulation.silk_lifetime[idx] = 0.0


@ti.kernel
def update_beetle_stuck_silk_positions(
    # Blue beetle state
    blue_x: ti.f32, blue_y: ti.f32, blue_z: ti.f32,
    blue_rotation: ti.f32, blue_pitch: ti.f32, blue_roll: ti.f32,
    blue_horn_pitch: ti.f32, blue_horn_yaw: ti.f32, blue_tail_pitch: ti.f32,
    blue_horn_type_id: ti.i32, blue_body_length: ti.i32, blue_back_height: ti.i32,
    blue_spray_aim: ti.f32, blue_spider_aim: ti.f32, blue_default_horn_pitch: ti.f32,
    # Red beetle state
    red_x: ti.f32, red_y: ti.f32, red_z: ti.f32,
    red_rotation: ti.f32, red_pitch: ti.f32, red_roll: ti.f32,
    red_horn_pitch: ti.f32, red_horn_yaw: ti.f32, red_tail_pitch: ti.f32,
    red_horn_type_id: ti.i32, red_body_length: ti.i32, red_back_height: ti.i32,
    red_spray_aim: ti.f32, red_spider_aim: ti.f32, red_default_horn_pitch: ti.f32,
    # Ball state
    ball_x: ti.f32, ball_y: ti.f32, ball_z: ti.f32,
    ball_rotation: ti.f32, ball_pitch: ti.f32, ball_roll: ti.f32, ball_active: ti.i32
):
    """Update world positions of silk stuck to beetles/ball - call after beetle render"""
    for idx in range(simulation.num_silk[None]):
        # Skip inactive particles (free list pattern)
        if simulation.silk_active[idx] == 0:
            continue

        stuck_type = simulation.silk_stuck[idx]

        if stuck_type == 2:  # Beetle-stuck silk
            stuck_beetle = simulation.silk_stuck_beetle[idx]
            voxel_idx = simulation.silk_stuck_voxel_idx[idx]
            offset = simulation.silk_stuck_offset[idx]

            if stuck_beetle == 0:  # Blue beetle
                world_pos = transform_body_voxel_to_world(
                    voxel_idx, 1,
                    blue_x, blue_y, blue_z,
                    blue_rotation, blue_pitch, blue_roll,
                    blue_horn_pitch, blue_horn_yaw, blue_tail_pitch,
                    blue_horn_type_id, blue_body_length, blue_back_height,
                    blue_spray_aim, blue_spider_aim, blue_default_horn_pitch
                )
                simulation.silk_pos[idx] = world_pos + offset
            else:  # Red beetle
                world_pos = transform_body_voxel_to_world(
                    voxel_idx, 0,
                    red_x, red_y, red_z,
                    red_rotation, red_pitch, red_roll,
                    red_horn_pitch, red_horn_yaw, red_tail_pitch,
                    red_horn_type_id, red_body_length, red_back_height,
                    red_spray_aim, red_spider_aim, red_default_horn_pitch
                )
                simulation.silk_pos[idx] = world_pos + offset

        elif stuck_type == 3 and ball_active == 1:  # Ball-stuck silk
            offset = simulation.silk_stuck_offset[idx]

            # Rotate offset with ball's rotation (yaw -> pitch -> roll)
            # Step 1: Yaw (around Y-axis)
            cos_yaw = ti.cos(ball_rotation)
            sin_yaw = ti.sin(ball_rotation)
            temp_x = offset.x * cos_yaw - offset.z * sin_yaw
            temp_z = offset.x * sin_yaw + offset.z * cos_yaw
            temp_y = offset.y

            # Step 2: Pitch (around Z-axis, nose up/down)
            cos_pitch = ti.cos(ball_pitch)
            sin_pitch = ti.sin(ball_pitch)
            rot_x = temp_x * cos_pitch - temp_y * sin_pitch
            rot_y = temp_x * sin_pitch + temp_y * cos_pitch
            rot_z = temp_z

            # Step 3: Roll (around X-axis, side tilt)
            cos_roll = ti.cos(ball_roll)
            sin_roll = ti.sin(ball_roll)
            final_y = rot_y * cos_roll - rot_z * sin_roll
            final_z = rot_y * sin_roll + rot_z * cos_roll
            final_x = rot_x

            simulation.silk_pos[idx] = ti.math.vec3(ball_x + final_x, ball_y + final_y, ball_z + final_z)


@ti.kernel
def cleanup_dead_silk():
    """Remove expired silk particles by compacting array"""
    write_idx = 0

    ti.loop_config(serialize=True)
    for read_idx in range(simulation.num_silk[None]):
        # Check both lifetime AND active flag (free list pattern)
        if simulation.silk_lifetime[read_idx] > 0.0 and simulation.silk_active[read_idx] == 1:
            if write_idx != read_idx:
                simulation.silk_pos[write_idx] = simulation.silk_pos[read_idx]
                simulation.silk_vel[write_idx] = simulation.silk_vel[read_idx]
                simulation.silk_color[write_idx] = simulation.silk_color[read_idx]
                simulation.silk_lifetime[write_idx] = simulation.silk_lifetime[read_idx]
                simulation.silk_owner[write_idx] = simulation.silk_owner[read_idx]
                simulation.silk_stuck[write_idx] = simulation.silk_stuck[read_idx]
                # Copy beetle-sticking tracking fields
                simulation.silk_stuck_beetle[write_idx] = simulation.silk_stuck_beetle[read_idx]
                simulation.silk_stuck_voxel_idx[write_idx] = simulation.silk_stuck_voxel_idx[read_idx]
                simulation.silk_stuck_offset[write_idx] = simulation.silk_stuck_offset[read_idx]
                simulation.silk_active[write_idx] = 1  # Mark compacted slot as active
            write_idx += 1
        else:
            # Particle is dead - counters already decremented in update_silk_particles
            pass

    simulation.num_silk[None] = write_idx


@ti.kernel
def count_floor_silk_under_beetles(blue_x: ti.f32, blue_z: ti.f32, red_x: ti.f32, red_z: ti.f32,
                                   ball_x: ti.f32, ball_z: ti.f32, ball_active: ti.i32):
    """Count floor silk particles near each beetle and ball for speed/friction effects"""
    FLOOR_SILK_RADIUS = 8.0  # How close counts as "under" the beetle
    BALL_SILK_RADIUS = 6.0   # Smaller radius for ball (ball is smaller than beetle)
    RADIUS_SQ = FLOOR_SILK_RADIUS * FLOOR_SILK_RADIUS
    BALL_RADIUS_SQ = BALL_SILK_RADIUS * BALL_SILK_RADIUS

    # Reset counters
    simulation.silk_under_blue[None] = 0
    simulation.silk_under_red[None] = 0
    simulation.silk_under_ball[None] = 0

    for idx in range(simulation.num_silk[None]):
        # Skip inactive particles (free list pattern)
        if simulation.silk_active[idx] == 0:
            continue
        if simulation.silk_stuck[idx] == 1:  # Floor silk only
            pos = simulation.silk_pos[idx]

            # Check distance to blue beetle
            dx_blue = pos.x - blue_x
            dz_blue = pos.z - blue_z
            if dx_blue * dx_blue + dz_blue * dz_blue < RADIUS_SQ:
                ti.atomic_add(simulation.silk_under_blue[None], 1)

            # Check distance to red beetle
            dx_red = pos.x - red_x
            dz_red = pos.z - red_z
            if dx_red * dx_red + dz_red * dz_red < RADIUS_SQ:
                ti.atomic_add(simulation.silk_under_red[None], 1)

            # Check distance to ball (if active)
            if ball_active == 1:
                dx_ball = pos.x - ball_x
                dz_ball = pos.z - ball_z
                if dx_ball * dx_ball + dz_ball * dz_ball < BALL_RADIUS_SQ:
                    ti.atomic_add(simulation.silk_under_ball[None], 1)


@ti.kernel
def check_silk_ball_collision(ball_x: ti.f32, ball_y: ti.f32, ball_z: ti.f32, ball_radius: ti.f32,
                               ball_rotation: ti.f32, ball_pitch: ti.f32, ball_roll: ti.f32):
    """Check flying silk against ball and stick if hit"""
    STICK_RADIUS = ball_radius + 1.5  # Ball radius plus small buffer
    STICK_RADIUS_SQ = STICK_RADIUS * STICK_RADIUS

    for idx in range(simulation.num_silk[None]):
        # Skip inactive particles (free list pattern)
        if simulation.silk_active[idx] == 0:
            continue
        if simulation.silk_stuck[idx] != 0:  # Only check flying silk
            continue

        pos = simulation.silk_pos[idx]

        # Distance to ball center
        dx = pos.x - ball_x
        dy = pos.y - ball_y
        dz = pos.z - ball_z
        dist_sq = dx * dx + dy * dy + dz * dz

        if dist_sq < STICK_RADIUS_SQ:
            # Hit the ball! Stick to it
            simulation.silk_stuck[idx] = 3  # New value: stuck to ball
            simulation.silk_stuck_beetle[idx] = 2  # 2 = ball (not 0=blue, 1=red)
            # Store offset in BALL-LOCAL space (inverse rotate world offset)
            dist = ti.sqrt(dist_sq)
            # Initialize world offset (must be before if/else for Taichi scoping)
            world_off_x = ball_radius
            world_off_y = 0.0
            world_off_z = 0.0
            if dist > 0.1:
                # Normalize and place on ball surface (world offset)
                world_off_x = dx / dist * ball_radius
                world_off_y = dy / dist * ball_radius
                world_off_z = dz / dist * ball_radius

            # Inverse rotate: roll^-1 -> pitch^-1 -> yaw^-1
            # Step 1: Inverse roll (around X, negative angle)
            cos_roll = ti.cos(-ball_roll)
            sin_roll = ti.sin(-ball_roll)
            r1_y = world_off_y * cos_roll - world_off_z * sin_roll
            r1_z = world_off_y * sin_roll + world_off_z * cos_roll
            r1_x = world_off_x

            # Step 2: Inverse pitch (around Z, negative angle)
            cos_pitch = ti.cos(-ball_pitch)
            sin_pitch = ti.sin(-ball_pitch)
            r2_x = r1_x * cos_pitch - r1_y * sin_pitch
            r2_y = r1_x * sin_pitch + r1_y * cos_pitch
            r2_z = r1_z

            # Step 3: Inverse yaw (around Y, negative angle)
            cos_yaw = ti.cos(-ball_rotation)
            sin_yaw = ti.sin(-ball_rotation)
            local_x = r2_x * cos_yaw - r2_z * sin_yaw
            local_z = r2_x * sin_yaw + r2_z * cos_yaw
            local_y = r2_y

            simulation.silk_stuck_offset[idx] = ti.math.vec3(local_x, local_y, local_z)
            simulation.silk_vel[idx] = ti.math.vec3(0.0, 0.0, 0.0)
            simulation.silk_lifetime[idx] = SILK_LIFETIME_STUCK
            ti.atomic_add(simulation.silk_on_ball[None], 1)


# ============== END SPIDER SILK SYSTEM ==============


# ============== LADYBUG CHEERLEADER SYSTEM ==============
# Decorative ladybugs that dance when you win a round

class Ladybug:
    """Ladybug cheerleader - visual only, no collision"""
    def __init__(self, x, z, rotation=0.0):
        self.x = x
        self.z = z
        self.y = 0.0  # Ground level
        self.rotation = rotation  # Facing direction
        self.body_tilt = math.radians(30)  # Tilted back slightly (less extreme so head visible)
        self.body_roll = 0.0  # Left/right tilt (roll)
        self.kick_phase = 0.0  # 0-2π animation phase
        self.shell_open = 0.0  # 0.0-1.0 for shell clap
        self.antenna_phase = 0.0  # Antenna bounce
        self.head_turn_phase = 0.0  # Independent head look-around animation
        self.visible = True
        # Track previous position for proper voxel clearing on movement
        self.prev_x = x
        self.prev_y = 0.0
        self.prev_z = z

def generate_ladybug_geometry():
    """Generate ladybug body voxels (shell dome + head + spots + wings)

    Returns: (body_voxels, leg_voxels, wing_voxels) where each voxel is (dx, dy, dz, voxel_type)
    Local coordinates: X = forward, Y = up, Z = left/right
    Scale: Larger size, radius ~8 voxels for visibility
    """
    body_voxels = []
    leg_voxels = [[], [], [], [], [], []]  # 6 legs
    wing_voxels = [[], []]  # Left wing, Right wing

    # SHELL DOME - hemispherical top (bigger!)
    shell_radius = 8

    # Define round spot centers on the shell surface (x, y, z, radius)
    # Positioned lower and further out to be visible from side/bottom angles
    spot_centers = [
        (4, 3, -5, 1.8),   # Front left - lower and wider
        (4, 3, 5, 1.8),    # Front right - lower and wider
        (0, 3, -7, 1.8),   # Middle left - lower and at edge
        (0, 3, 7, 1.8),    # Middle right - lower and at edge
        (-4, 3, -5, 1.8),  # Back left - lower and wider
        (-4, 3, 5, 1.8),   # Back right - lower and wider
        (-5, 4, 0, 1.8),   # Center back
    ]

    for dx in range(-shell_radius, shell_radius + 1):
        for dy in range(0, shell_radius + 1):  # Only top half
            for dz in range(-shell_radius, shell_radius + 1):
                dist = math.sqrt(dx*dx + dy*dy + dz*dz)
                if dist <= shell_radius and dist > shell_radius - 1.8:
                    # Shell surface - check if near any spot center
                    is_spot = False
                    for sx, sy, sz, sr in spot_centers:
                        spot_dist = math.sqrt((dx-sx)**2 + (dy-sy)**2 + (dz-sz)**2)
                        if spot_dist <= sr:
                            is_spot = True
                            break

                    if is_spot:
                        body_voxels.append((dx, dy, dz, simulation.LADYBUG_SPOTS))
                    else:
                        body_voxels.append((dx, dy, dz, simulation.LADYBUG_SHELL))

    # UNDERSIDE - flat belly
    for dx in range(-6, 7):
        for dz in range(-6, 7):
            dist = math.sqrt(dx*dx + dz*dz)
            if dist <= 6:
                body_voxels.append((dx, -1, dz, simulation.LADYBUG_HEAD))  # Black underside

    # HEAD - dome at front, clearly outside shell
    head_x = shell_radius + 3  # Well in front of shell
    head_y = 2
    for dx in range(-2, 3):
        for dy in range(-1, 4):
            for dz in range(-2, 3):
                dist = math.sqrt(dx*dx + dy*dy + dz*dz)
                if dist <= 2.5:
                    body_voxels.append((head_x + dx, head_y + dy, dz, simulation.LADYBUG_HEAD))

    # ANTENNAE - thin lines going up, forward, and spreading outward
    # Use smaller Y step to avoid gaps (2 voxels per Y level)
    for i in range(8):
        ant_x = head_x + 2 + i  # Start from front of head, go forward
        ant_y = head_y + 2 + int(i * 0.6)  # Gentler slope - no gaps
        ant_z_spread = 2 + int(i * 0.4)  # Spread outward as they extend
        # Left antenna - single voxel
        body_voxels.append((ant_x, ant_y, -ant_z_spread, simulation.LADYBUG_HEAD))
        # Right antenna - single voxel
        body_voxels.append((ant_x, ant_y, ant_z_spread, simulation.LADYBUG_HEAD))

    # WINGS - curved line with 2 voxel thickness (Y direction)
    wing_length = 11
    for i in range(wing_length):
        wing_x = 1 - i  # Start forward, extend backward
        wing_y = shell_radius - 1  # At top of shell (7)
        wing_z_offset = int(i * 0.7)  # Gentle outward curve

        # Left wing - 2 voxels tall
        wing_voxels[0].append((wing_x, wing_y, -5 - wing_z_offset))
        wing_voxels[0].append((wing_x, wing_y + 1, -5 - wing_z_offset))
        # Right wing - 2 voxels tall
        wing_voxels[1].append((wing_x, wing_y, 5 + wing_z_offset))
        wing_voxels[1].append((wing_x, wing_y + 1, 5 + wing_z_offset))

    # LEGS - 6 legs (3 pairs), scaled up
    leg_positions = [
        (3, -1, -5),   # Front left - kick leg
        (3, -1, 5),    # Front right - kick leg
        (-1, -1, -6),  # Middle left
        (-1, -1, 6),   # Middle right
        (-5, -1, -5),  # Rear left - anchor
        (-5, -1, 5),   # Rear right - anchor
    ]

    for leg_id, (lx, ly, lz) in enumerate(leg_positions):
        leg = []
        z_dir = -1 if lz < 0 else 1

        # Front legs (0, 1) - single voxel width, they look good
        if leg_id < 2:
            leg.append((0, 0, 0, simulation.LADYBUG_LEGS))
            leg.append((0, -1, z_dir, simulation.LADYBUG_LEGS))
            leg.append((0, -2, z_dir * 2, simulation.LADYBUG_LEGS))
            leg.append((0, -3, z_dir * 3, simulation.LADYBUG_LEGS))
            leg.append((0, -4, z_dir * 3, simulation.LADYBUG_LEGS))
            leg.append((0, -5, z_dir * 3, simulation.LADYBUG_LEGS))
        else:
            # Middle and rear legs (2, 3, 4, 5) - single voxel width
            for seg in range(6):
                y_off = -seg
                z_off = z_dir * min(seg, 3)
                leg.append((0, y_off, z_off, simulation.LADYBUG_LEGS))

        leg_voxels[leg_id] = leg

    return body_voxels, leg_voxels, wing_voxels

