        def colors_match(c1, c2, tol=0.001):
            return abs(c1[0] - c2[0]) < tol and abs(c1[1] - c2[1]) < tol and abs(c1[2] - c2[2]) < tol
        bg_is_default = colors_match(window.background_color, default_bg)
